/* Blackboard lessons for the probability cheat sheet: one lesson per card (and per row of the contingency table).
   Pictures: Venn diagrams, trees, dice grids, bar charts and densities. Texts: 'en|fr|es|ja|zh'. */
(function () {
  const R = String.raw;
  const IDEA = 'The idea|L’idée|La idea|考え方|思路', EX = 'Worked example|Exemple résolu|Ejemplo resuelto|例題|例题', YOUR = 'Your turn|À vous|Te toca|やってみよう|轮到你了';
  const TRY = 'Work it out on paper, type the answer (a fraction or a decimal) and check it. Each hint writes the next line of the solution on the board.|Faites le calcul sur papier, tapez la réponse (fraction ou décimal) et vérifiez. Chaque indice écrit la ligne suivante de la solution au tableau.|Hazlo en papel, escribe la respuesta (fracción o decimal) y compruébala. Cada pista escribe en la pizarra la siguiente línea de la solución.|紙で計算し、答え（分数か小数）を入力して確かめましょう。ヒントごとに解答が 1 行ずつ黒板に書かれます。|先在纸上算，输入答案（分数或小数）并检查。每次提示会在黑板上写出解答的下一行。';
  const F = (tex, o = {}) => ['w', R`\displaystyle ` + tex, Object.assign({ s: 26 }, o)];
  const Y = (tex, o = {}) => F(tex, Object.assign({ c: 'y' }, o));
  const W = (txt, o = {}) => ['t', txt, Object.assign({ s: 18, c: 'b' }, o)];
  const H = name => ['t', name, { head: true, s: 16, c: 'y' }];
  const Z = (x, y) => [x, y, 0];
  // give a group of scene items quick, staggered delays (the default is 300 ms per item, too slow for grids)
  const SEQ = (items, d0 = 200, step = 40) => items.map((a, i) => { const o = a[a.length - 1]; if (o && typeof o === 'object' && !Array.isArray(o)) o.d = d0 + i * step; return a; });
  const S2 = (c, r, axes = false) => ['3d', { flat: true, axes, c: [c[0], c[1], 0], r }];
  const CI = (o, r, c, fill = 0.16) => ['circ3', Z(...o), [0, 0, 1], r, { c, fill }];
  const LB = (p, t, c = 'y', size) => ['lab3', Z(...p), t, Object.assign({ c }, size ? { size } : {})];
  const SG = (p, q, c = 'chalk', o = {}) => ['seg', Z(...p), Z(...q), Object.assign({ c }, o)];
  const PT = (p, lab, c = 'y', o = {}) => ['pt3', Z(...p), lab || '', Object.assign({ c }, o)];
  const RECT = (x0, y0, x1, y1, c = 'b', fill = 0.3) => ['poly3', [Z(x0, y0), Z(x1, y0), Z(x1, y1), Z(x0, y1)], { c, fill }];
  // a Venn diagram of A and B inside the universe
  const VENN = (la = 'A', lb = 'B', extra = []) => [S2([0, 0], 2.2), ...SEQ([RECT(-2.4, -1.6, 2.4, 1.6, 'chalk', 0.03), CI([-0.6, 0], 1.1, 'b'), CI([0.6, 0], 1.1, 'p'), LB([-1.3, 1.1], la, 'b'), LB([1.2, 1.1], lb, 'p'), LB([-2.2, 1.35], 'Ω', 'chalk'), ...extra], 200, 160)];
  // a two-level tree: first branch probability p (labels a, ā), then q1 / q2 for the event on each branch
  const TREE = (p, q1, q2, la, lb) => [S2([1.5, 0], 2.2), ...SEQ([
    SG([0, 0], [1.5, 1.2], 'b'), SG([0, 0], [1.5, -1.2], 'b'), SG([1.5, 1.2], [3, 1.8], 'y'), SG([1.5, 1.2], [3, 0.6], 'chalk'), SG([1.5, -1.2], [3, -0.6], 'y'), SG([1.5, -1.2], [3, -1.8], 'chalk'),
    LB([0.45, 0.85], p, 'b'), LB([0.45, -1.05], '1 − ' + p, 'b'), LB([1.5, 1.4], la[0], 'b'), LB([1.5, -1.0], la[1], 'b'),
    LB([2.0, 1.75], q1, 'y'), LB([2.0, -0.55], q2, 'y'), LB([3.1, 1.8], lb[0], 'y'), LB([3.1, 0.6], lb[1], 'chalk'), LB([3.1, -0.6], lb[0], 'y'), LB([3.1, -1.8], lb[1], 'chalk')], 200, 90)];
  // a bar chart: probabilities p[k] at x = k0 + k (height scaled by s)
  const BARS = (ps, k0 = 0, s = 1, c = 'b', hi = -1) => SEQ(ps.map((p, k) => RECT(k0 + k - 0.38, 0, k0 + k + 0.38, p * s, k === hi ? 'y' : c, k === hi ? 0.55 : 0.3)), 200, 70);
  const AX = (xw, yw) => ['ax', { xw, yw }], P = (eq, c = 'y', o = {}) => ['p', 'y=' + eq, Object.assign({ c }, o)], SH = (a, b) => ['sh', a, b];
  const N01 = 'e^(-x^2/2)/sqrt(2pi)';
  const L = {};
  const lesson = (key, head, idea, ex, your) => {
    L[key] = [{ t: IDEA, s: idea.s, a: [H(head), ...idea.a] }, { t: EX, s: ex.s, a: [['clr'], H(head), ...ex.a] },
      { t: YOUR, s: your.s || TRY, a: [['clr'], H(head), ...(your.a || [])], ex: your.ex }];
  };
  const C = (a, b) => { let r = 1; for (let k = 1; k <= b; k++) r = r * (a - b + k) / k; return r; };
  const binom = (n, p) => [...Array(n + 1)].map((_, k) => C(n, k) * p ** k * (1 - p) ** (n - k));

  // =============================== Basics ===============================
  lesson('Basics/Equally likely outcomes', 'Equally likely outcomes|Équiprobabilité|Casos equiprobables|同様に確からしい場合|等可能事件',
    { s: R`When every outcome has the same chance (a fair die, a well-shuffled deck), the probability of an event is just counting: favourable outcomes divided by all possible outcomes. The hard part is listing $\Omega$ correctly — with two dice there are 36 ordered outcomes, not 11 sums.|Quand toutes les issues ont la même chance (dé équilibré, jeu bien mélangé), la probabilité d’un événement se compte : cas favorables sur cas possibles. Le plus délicat est de bien lister $\Omega$ — avec deux dés il y a 36 issues ordonnées, pas 11 sommes.|Cuando todos los resultados tienen la misma probabilidad (dado equilibrado, baraja bien mezclada), la probabilidad de un suceso es contar: casos favorables entre casos posibles. Lo difícil es listar bien $\Omega$: con dos dados hay 36 resultados ordenados, no 11 sumas.|すべての結果が同じ確からしさ（公正なさいころ、よく切ったトランプ）なら、確率は数えるだけ：有利な場合の数 ÷ 全体の数。難しいのは $\Omega$ を正しく数えること（2 個のさいころは 11 通りの和ではなく 36 通り）。|当所有结果机会均等（均匀骰子、洗好的牌），事件概率就是计数：有利结果数除以全部结果数。难点是正确列出 $\Omega$——两颗骰子有 36 种有序结果，而不是 11 种和。`,
      a: [Y(R`P(A) = \frac{\lvert A\rvert}{\lvert\Omega\rvert}`, { s: 30 }), W('favourable / possible|cas favorables / cas possibles|casos favorables / casos posibles|有利な場合 / 全体|有利结果 / 全部结果'),
        S2([3.5, 3.5], 3.3), ...SEQ([...Array(36)].map((_, k) => { const a = k % 6 + 1, b = Math.floor(k / 6) + 1; return PT([a, b], '', a + b === 8 ? 'y' : 'chalk'); }), 200, 25)] },
    { s: R`One card from a 52-card deck: $P(\heartsuit) = \tfrac{13}{52} = \tfrac14$; $P(\text{king}) = \tfrac{4}{52} = \tfrac1{13}$.|Une carte d’un jeu de 52 : $P(\heartsuit) = \tfrac{13}{52} = \tfrac14$ ; $P(\text{roi}) = \tfrac{4}{52} = \tfrac1{13}$.|Una carta de una baraja de 52: $P(\heartsuit) = \tfrac{13}{52} = \tfrac14$; $P(\text{rey}) = \tfrac{4}{52} = \tfrac1{13}$.|52 枚から 1 枚：$P(\heartsuit) = \tfrac14$、$P(\text{K}) = \tfrac1{13}$。|52 张牌中抽一张：$P(\heartsuit) = \tfrac14$，$P(\text{K}) = \tfrac1{13}$。`,
      a: [F(R`P(\heartsuit) = \frac{13}{52} = \frac14`), Y(R`P(\text{king}) = \frac{4}{52} = \frac{1}{13}`)] },
    { a: [F(R`\lvert\Omega\rvert = 36`), S2([3.5, 3.5], 3.3), ...SEQ([...Array(36)].map((_, k) => PT([k % 6 + 1, Math.floor(k / 6) + 1], '', 'chalk')), 200, 25)],
      ex: { k: 'val', v: '5/36', q: R`Two fair dice are rolled. Find $P(\text{sum} = 8)$.|On lance deux dés équilibrés. Calculez $P(\text{somme} = 8)$.|Se lanzan dos dados equilibrados. Halla $P(\text{suma} = 8)$.|公正なさいころを 2 個投げる。$P(\text{和} = 8)$ を求めよ。|掷两颗均匀骰子，求 $P(\text{和} = 8)$。`,
        sol: [R`(2,6),(3,5),(4,4),(5,3),(6,2):\ 5\ \text{ways}`, R`P = \frac{5}{36}`] } });

  lesson('Basics/Complement', 'The complement|L’événement contraire|El suceso contrario|余事象|对立事件',
    { s: R`“Not $A$” happens exactly when $A$ does not, and together they fill $\Omega$, so their probabilities add up to 1. When “not $A$” is simpler to count, compute it and subtract from 1.|« Non $A$ » se réalise exactement quand $A$ ne se réalise pas ; ensemble ils remplissent $\Omega$, donc leurs probabilités font 1. Si le contraire est plus simple à compter, on le calcule et on retranche de 1.|«No $A$» ocurre justo cuando no ocurre $A$, y juntos llenan $\Omega$, así que sus probabilidades suman 1. Si el contrario es más fácil de contar, calcúlalo y réstalo de 1.|「$A$ でない」は $A$ が起こらないときちょうど起こり、両者で $\Omega$ を満たすので確率の和は 1。余事象の方が数えやすければ、それを 1 から引く。|“非 $A$”恰在 $A$ 不发生时发生，两者合起来是 $\Omega$，概率之和为 1。若对立事件更好算，就算它再用 1 减。`,
      a: [Y(R`P(\bar A) = 1 - P(A)`, { s: 30 }), S2([0, 0], 2.2), RECT(-2.4, -1.6, 2.4, 1.6, 'p', 0.16), CI([0, 0], 1.1, 'b', 0.5), LB([-0.15, 0], 'A', 'chalk'), LB([1.6, 1.2], 'Ā', 'p')] },
    { s: R`Three coins: “not all tails” is the complement of TTT, so $P = 1 - \tfrac18 = \tfrac78$ — much quicker than counting the seven other outcomes.|Trois pièces : « pas tout pile » est le contraire de PPP, donc $P = 1 - \tfrac18 = \tfrac78$ — bien plus rapide que de compter les sept autres issues.|Tres monedas: «no todo cruces» es el contrario de XXX, así que $P = 1 - \tfrac18 = \tfrac78$, mucho más rápido que contar los otros siete resultados.|硬貨 3 枚：「全部裏ではない」は TTT の余事象で $1 - \tfrac18 = \tfrac78$。|三枚硬币：“不全是反面”是 TTT 的对立事件，$P = 1 - \tfrac18 = \tfrac78$。`,
      a: [F(R`P(TTT) = \tfrac18`), Y(R`P(\text{not all tails}) = 1 - \tfrac18 = \tfrac78`)] },
    { a: [F(R`\text{two coins}`)],
      ex: { k: 'val', v: '3/4', q: R`Two coins are tossed. Find the probability that they are NOT both heads.|On lance deux pièces. Calculez la probabilité qu’elles ne donnent PAS deux faces.|Se lanzan dos monedas. Halla la probabilidad de que NO salgan dos caras.|硬貨を 2 枚投げる。2 枚とも表ではない確率を求めよ。|掷两枚硬币，求“不是两个都正面”的概率。`,
        sol: [R`P(HH) = \tfrac14`, R`1 - \tfrac14 = \tfrac34`] } });

  lesson('Basics/At least one', '“At least one”|« Au moins un »|«Al menos uno»|「少なくとも 1 回」|“至少一次”',
    { s: R`“At least one” has many cases (exactly 1, exactly 2, …) but its complement has only one: “none at all”. With independent trials, “none” is a product of probabilities.|« Au moins un » recouvre beaucoup de cas (exactement 1, exactement 2, …) mais son contraire n’en a qu’un : « aucun ». Avec des épreuves indépendantes, « aucun » est un produit de probabilités.|«Al menos uno» tiene muchos casos (exactamente 1, exactamente 2…) pero su contrario solo uno: «ninguno». Con pruebas independientes, «ninguno» es un producto de probabilidades.|「少なくとも 1 回」は場合が多いが、余事象「1 回もない」は 1 つだけ。独立な試行なら「1 回もない」は確率の積。|“至少一次”情形很多（恰 1 次、恰 2 次……），对立事件只有一个：“一次也没有”。独立试验时“一次也没有”是概率之积。`,
      a: [Y(R`P(X \ge 1) = 1 - P(X = 0)`, { s: 30 })] },
    { s: R`Four rolls of a die, at least one six: $1 - \left(\tfrac56\right)^4 = 1 - \tfrac{625}{1296} \approx 0.518$ — slightly better than even.|Quatre lancers de dé, au moins un six : $1 - \left(\tfrac56\right)^4 \approx 0{,}518$ — un peu plus d’une chance sur deux.|Cuatro tiradas de un dado, al menos un seis: $1 - \left(\tfrac56\right)^4 \approx 0{,}518$, algo más que la mitad.|さいころ 4 回で少なくとも 1 回 6：$1 - \left(\tfrac56\right)^4 \approx 0.518$。|掷骰子 4 次至少一次 6 点：$1 - \left(\tfrac56\right)^4 \approx 0.518$。`,
      a: [F(R`P(\text{no six}) = \left(\tfrac56\right)^4`), Y(R`P(\ge 1\ \text{six}) = 1 - \tfrac{625}{1296} \approx 0.518`)] },
    { a: [F(R`p = 0.4,\quad 3\ \text{shots}`)],
      ex: { k: 'val', v: '0.784', q: R`Each of 3 independent shots hits with probability 0.4. Find the probability of at least one hit.|Chacun de 3 tirs indépendants touche avec la probabilité 0,4. Calculez la probabilité d’au moins un succès.|Cada uno de 3 tiros independientes acierta con probabilidad 0,4. Halla la probabilidad de al menos un acierto.|独立な 3 回の射撃がそれぞれ確率 0.4 で命中する。少なくとも 1 回命中する確率を求めよ。|三次独立射击每次命中概率 0.4，求至少命中一次的概率。`,
        sol: [R`P(\text{no hit}) = 0.6^3 = 0.216`, R`1 - 0.216 = 0.784`] } });

  lesson('Basics/Union', 'The union (A or B)|La réunion (A ou B)|La unión (A o B)|和事象（A または B）|并事件（A 或 B）',
    { s: R`Adding $P(A)$ and $P(B)$ counts the overlap twice — subtract it once. In the Venn diagram, the middle lens belongs to both circles.|En additionnant $P(A)$ et $P(B)$ on compte l’intersection deux fois — on la retire une fois. Sur le diagramme, la lentille centrale appartient aux deux cercles.|Al sumar $P(A)$ y $P(B)$ se cuenta dos veces la intersección: réstala una vez. En el diagrama, la lente central pertenece a los dos círculos.|$P(A)$ と $P(B)$ を足すと重なりを 2 回数えるので 1 回引く。図の真ん中のレンズは両方の円に属する。|$P(A)$ 加 $P(B)$ 把重叠部分算了两次——减去一次。维恩图中间的透镜形属于两个圆。`,
      a: [Y(R`P(A \cup B) = P(A) + P(B) - P(A \cap B)`, { s: 24 }), ...VENN('A', 'B', [LB([-0.12, 0], 'A∩B', 'y')])] },
    { s: R`$P(A) = 0.5$, $P(B) = 0.4$, $P(A \cap B) = 0.2$: $P(A \cup B) = 0.5 + 0.4 - 0.2 = 0.7$.|$P(A) = 0{,}5$, $P(B) = 0{,}4$, $P(A \cap B) = 0{,}2$ : $P(A \cup B) = 0{,}7$.|$P(A) = 0{,}5$, $P(B) = 0{,}4$, $P(A \cap B) = 0{,}2$: $P(A \cup B) = 0{,}7$.|$P(A) = 0.5$, $P(B) = 0.4$, $P(A \cap B) = 0.2$ なら $P(A \cup B) = 0.7$。|$P(A) = 0.5$，$P(B) = 0.4$，$P(A \cap B) = 0.2$：$P(A \cup B) = 0.7$。`,
      a: [Y(R`P(A \cup B) = 0.5 + 0.4 - 0.2 = 0.7`), ...VENN('A', 'B', [LB([-1.1, 0], '0.3', 'chalk'), LB([-0.1, 0], '0.2', 'y'), LB([0.9, 0], '0.2', 'chalk')])] },
    { a: [F(R`\heartsuit\ \text{or king}`)],
      ex: { k: 'val', v: '4/13', q: R`One card is drawn from 52. Find $P(\text{heart or king})$.|On tire une carte parmi 52. Calculez $P(\text{cœur ou roi})$.|Se saca una carta de 52. Halla $P(\text{corazón o rey})$.|52 枚から 1 枚引く。$P(\text{ハートまたは K})$ を求めよ。|从 52 张牌中抽一张，求 $P(\text{红心或 K})$。`,
        sol: [R`\frac{13}{52} + \frac{4}{52} - \frac{1}{52}`, R`= \frac{16}{52} = \frac{4}{13}`] } });

  lesson('Basics/Incompatible events', 'Incompatible events|Événements incompatibles|Sucesos incompatibles|排反事象|互斥事件',
    { s: R`If $A$ and $B$ cannot happen together, there is no overlap to subtract, and the probabilities simply add. Typical case: different values of the same roll.|Si $A$ et $B$ ne peuvent pas se produire ensemble, il n’y a pas d’intersection à retirer : les probabilités s’ajoutent. Cas typique : différentes valeurs d’un même lancer.|Si $A$ y $B$ no pueden ocurrir a la vez, no hay intersección que restar y las probabilidades se suman. Caso típico: valores distintos de una misma tirada.|$A$ と $B$ が同時に起こらなければ引く重なりはなく、確率はそのまま足せる。典型例：同じ試行の異なる値。|若 $A$、$B$ 不能同时发生，就没有重叠要减，概率直接相加。典型：同一次投掷的不同结果。`,
      a: [Y(R`A \cap B = \varnothing \Rightarrow P(A \cup B) = P(A) + P(B)`, { s: 24 }), S2([0, 0], 2.2), RECT(-2.4, -1.6, 2.4, 1.6, 'chalk', 0.03), CI([-1.2, 0], 0.9, 'b'), CI([1.2, 0], 0.9, 'p'), LB([-1.3, 0], 'A', 'chalk'), LB([1.1, 0], 'B', 'chalk')] },
    { s: R`One die, “1 or 6”: the two cannot happen at once, so $P = \tfrac16 + \tfrac16 = \tfrac13$.|Un dé, « 1 ou 6 » : impossibles en même temps, donc $P = \tfrac16 + \tfrac16 = \tfrac13$.|Un dado, «1 o 6»: no pueden ocurrir a la vez, así que $P = \tfrac16 + \tfrac16 = \tfrac13$.|さいころ 1 個で「1 または 6」：同時に起こらないので $\tfrac13$。|一颗骰子“1 或 6”：不能同时发生，$P = \tfrac13$。`,
      a: [Y(R`P(1\ \text{or}\ 6) = \tfrac16 + \tfrac16 = \tfrac13`)] },
    { a: [F(R`\text{two dice:}\ \Sigma = 7\ \text{or}\ \Sigma = 11`)],
      ex: { k: 'val', v: '2/9', q: R`Two dice: find $P(\text{sum} = 7\ \text{or}\ \text{sum} = 11)$.|Deux dés : calculez $P(\text{somme} = 7\ \text{ou}\ 11)$.|Dos dados: halla $P(\text{suma} = 7\ \text{o}\ 11)$.|さいころ 2 個：$P(\text{和が 7 または 11})$ を求めよ。|两颗骰子：求 $P(\text{和为 7 或 11})$。`,
        sol: [R`P(7) = \tfrac{6}{36},\quad P(11) = \tfrac{2}{36}`, R`\tfrac{8}{36} = \tfrac29`] } });

  lesson('Basics/Geometric probability', 'Geometric probability|Probabilités géométriques|Probabilidad geométrica|幾何確率|几何概型',
    { s: R`When the outcome is a random point (on a segment, in a region), “counting” becomes measuring: the probability is the favourable length or area divided by the total length or area.|Quand l’issue est un point au hasard (sur un segment, dans une région), « compter » devient mesurer : la probabilité est la longueur ou l’aire favorable divisée par la longueur ou l’aire totale.|Cuando el resultado es un punto al azar (en un segmento, en una región), «contar» pasa a ser medir: la probabilidad es la longitud o el área favorable entre la total.|結果がランダムな点（線分上、領域内）なら「数える」は「測る」になる：有利な長さ・面積 ÷ 全体の長さ・面積。|当结果是随机点（线段上、区域内）时，“计数”变成“度量”：概率等于有利长度或面积除以总长度或面积。`,
      a: [Y(R`P = \frac{\ell(A)}{\ell(\Omega)},\qquad P = \frac{S(A)}{S(\Omega)}`), S2([0, 0], 1.3), RECT(-1, -1, 1, 1, 'chalk', 0.06), CI([0, 0], 1, 'y', 0.3)] },
    { s: R`A point is chosen at random in $[0, 10]$. The chance that it lands in $[2, 5]$ is $\tfrac{3}{10}$: the length of the target over the length of the whole segment.|On choisit un point au hasard dans $[0, 10]$. La probabilité qu’il tombe dans $[2, 5]$ vaut $\tfrac{3}{10}$ : longueur de la cible sur longueur totale.|Se elige un punto al azar en $[0, 10]$. La probabilidad de que caiga en $[2, 5]$ es $\tfrac{3}{10}$: la longitud del objetivo entre la total.|$[0, 10]$ からランダムに点を選ぶ。$[2, 5]$ に入る確率は $\tfrac{3}{10}$。|在 $[0, 10]$ 中随机取点，落在 $[2, 5]$ 的概率为 $\tfrac{3}{10}$。`,
      a: [Y(R`P = \frac{5 - 2}{10} = \frac{3}{10}`), S2([5, 0], 6, true), SG([0, 0], [10, 0], 'chalk', { w: 4 }), SG([2, 0], [5, 0], 'y', { w: 8 })] },
    { a: [F(R`\text{square side } 2,\ \text{circle radius } 1`), S2([0, 0], 1.3), RECT(-1, -1, 1, 1, 'chalk', 0.06), CI([0, 0], 1, 'y', 0.3)],
      ex: { k: 'val', v: 'pi/4', q: R`A point is chosen at random in a square of side 2. Find the probability that it falls inside the inscribed circle.|On choisit un point au hasard dans un carré de côté 2. Calculez la probabilité qu’il soit dans le cercle inscrit.|Se elige un punto al azar en un cuadrado de lado 2. Halla la probabilidad de que caiga dentro del círculo inscrito.|一辺 2 の正方形内にランダムに点をとる。内接円の内部にある確率を求めよ。|在边长 2 的正方形内随机取点，求落在内切圆内的概率。`,
        sol: [R`S(\text{circle}) = \pi\cdot 1^2 = \pi,\quad S(\text{square}) = 4`, R`P = \frac\pi4 \approx 0.785`] } });

  // =============================== Conditional probability ===============================
  lesson('Conditional probability/Definition', 'Conditional probability|Probabilité conditionnelle|Probabilidad condicionada|条件付き確率|条件概率',
    { s: R`“Given $B$” means we already know $B$ happened: $B$ becomes the new universe. Inside it, the part where $A$ also happens is $A \cap B$, so $P(A \mid B)$ is the share of $B$ taken by $A \cap B$.|« Sachant $B$ » signifie qu’on sait que $B$ s’est produit : $B$ devient le nouvel univers. Dedans, la partie où $A$ a aussi lieu est $A \cap B$ : $P(A \mid B)$ est la part de $B$ occupée par $A \cap B$.|«Sabiendo $B$» significa que ya sabemos que ocurrió $B$: $B$ pasa a ser el nuevo universo. Dentro, la parte donde también ocurre $A$ es $A \cap B$, así que $P(A \mid B)$ es la proporción de $B$ que ocupa $A \cap B$.|「$B$ のもとで」は $B$ が起きたとわかっていること：$B$ が新しい全体。その中で $A$ も起こる部分が $A \cap B$ なので、$P(A \mid B)$ は $B$ に占める $A \cap B$ の割合。|“已知 $B$”表示知道 $B$ 已发生：$B$ 成为新的样本空间。其中 $A$ 也发生的部分是 $A \cap B$，所以 $P(A \mid B)$ 是 $A \cap B$ 在 $B$ 中所占的比例。`,
      a: [Y(R`P(A \mid B) = \frac{P(A \cap B)}{P(B)}`, { s: 30 }), W('B is the new universe|B devient l’univers|B es el nuevo universo|B が新しい全体|B 成为新的样本空间'), ...VENN('A', 'B', [CI([0.6, 0], 1.1, 'p', 0.35), LB([-0.12, 0], 'A∩B', 'y')])] },
    { s: R`$P(A \cap B) = 0.12$ and $P(B) = 0.3$: $P(A \mid B) = \tfrac{0.12}{0.3} = 0.4$. Knowing $B$ raised or lowered the chance of $A$ compared to $P(A)$.|$P(A \cap B) = 0{,}12$ et $P(B) = 0{,}3$ : $P(A \mid B) = \tfrac{0{,}12}{0{,}3} = 0{,}4$.|$P(A \cap B) = 0{,}12$ y $P(B) = 0{,}3$: $P(A \mid B) = \tfrac{0{,}12}{0{,}3} = 0{,}4$.|$P(A \cap B) = 0.12$, $P(B) = 0.3$：$P(A \mid B) = 0.4$。|$P(A \cap B) = 0.12$，$P(B) = 0.3$：$P(A \mid B) = 0.4$。`,
      a: [Y(R`P(A \mid B) = \frac{0.12}{0.3} = 0.4`)] },
    { a: [F(R`\text{one die:}\ P(6 \mid \text{even})`)],
      ex: { k: 'val', v: '1/3', q: R`A die shows an even number. What is the probability that it is a 6?|Un dé donne un nombre pair. Quelle est la probabilité que ce soit un 6 ?|Un dado da un número par. ¿Qué probabilidad hay de que sea un 6?|さいころの目が偶数だった。6 である確率を求めよ。|骰子点数为偶数，求它是 6 的概率。`,
        sol: [R`B = \{2, 4, 6\}`, R`P(6 \mid B) = \frac{1/6}{1/2} = \frac13`] } });

  lesson('Conditional probability/Multiplication rule', 'The multiplication rule|La formule des probabilités composées|La regla del producto|乗法定理|乘法公式',
    { s: R`To get both $B$ and $A$: first $B$ must happen, then $A$ given $B$. Multiply. This is how you handle draws without replacement: each new draw is conditioned on what is already gone.|Pour obtenir $B$ et $A$ : d’abord $B$, puis $A$ sachant $B$. On multiplie. C’est ainsi qu’on traite les tirages sans remise : chaque tirage dépend de ce qui est déjà parti.|Para obtener $B$ y $A$: primero debe ocurrir $B$ y luego $A$ sabiendo $B$. Se multiplica. Así se tratan las extracciones sin reemplazo: cada una depende de lo que ya salió.|$B$ と $A$ が両方起こるには、まず $B$、次に $B$ のもとで $A$。掛ける。非復元抽出はこうして扱う（毎回すでに出たものの条件付き）。|要 $B$ 与 $A$ 都发生：先 $B$，再在 $B$ 条件下 $A$，相乘。不放回抽取就这样处理：每次都以已取出的为条件。`,
      a: [Y(R`P(A \cap B) = P(B)\,P(A \mid B)`, { s: 30 })] },
    { s: R`Two cards without replacement, both aces: $\tfrac{4}{52}\cdot\tfrac{3}{51} = \tfrac{1}{221}$. The second fraction is $\tfrac{3}{51}$ because one ace and one card are gone.|Deux cartes sans remise, deux as : $\tfrac{4}{52}\cdot\tfrac{3}{51} = \tfrac{1}{221}$. La seconde fraction vaut $\tfrac{3}{51}$ car un as et une carte sont partis.|Dos cartas sin reemplazo, dos ases: $\tfrac{4}{52}\cdot\tfrac{3}{51} = \tfrac{1}{221}$. La segunda fracción es $\tfrac{3}{51}$ porque ya salió un as.|非復元で 2 枚ともエース：$\tfrac{4}{52}\cdot\tfrac{3}{51} = \tfrac{1}{221}$。|不放回抽两张都是 A：$\tfrac{4}{52}\cdot\tfrac{3}{51} = \tfrac{1}{221}$。`,
      a: [F(R`P = \frac{4}{52}\cdot\frac{3}{51}`), Y(R`= \frac{1}{221}`)] },
    { a: [F(R`5\ \text{red},\ 3\ \text{blue}`)],
      ex: { k: 'val', v: '5/14', q: R`An urn has 5 red and 3 blue balls. Two are drawn without replacement. Find the probability that both are red.|Une urne contient 5 boules rouges et 3 bleues. On en tire deux sans remise. Calculez la probabilité qu’elles soient rouges.|Una urna tiene 5 bolas rojas y 3 azules. Se sacan dos sin reemplazo. Halla la probabilidad de que las dos sean rojas.|赤 5 個、青 3 個の袋から 2 個を非復元で取り出す。2 個とも赤の確率を求めよ。|袋中有 5 红 3 蓝，不放回取两个，求都是红球的概率。`,
        sol: [R`\frac58\cdot\frac47`, R`= \frac{20}{56} = \frac{5}{14}`] } });

  lesson('Conditional probability/Independence', 'Independence|Indépendance|Independencia|独立|独立性',
    { s: R`$A$ and $B$ are independent when knowing one does not change the chance of the other: $P(A \mid B) = P(A)$. Equivalently, the probability of both is the product. Do not confuse with incompatible: incompatible events are very dependent.|$A$ et $B$ sont indépendants quand connaître l’un ne change pas la probabilité de l’autre : $P(A \mid B) = P(A)$. De façon équivalente, la probabilité des deux est le produit. À ne pas confondre avec incompatibles : des événements incompatibles sont très dépendants.|$A$ y $B$ son independientes cuando saber uno no cambia la probabilidad del otro: $P(A \mid B) = P(A)$. Equivalentemente, la probabilidad de ambos es el producto. No lo confundas con incompatibles: los incompatibles son muy dependientes.|一方を知っても他方の確率が変わらないとき独立：$P(A \mid B) = P(A)$。同値に、両方の確率は積。排反と混同しない（排反な事象は強く従属）。|知道一个不改变另一个的概率时两者独立：$P(A \mid B) = P(A)$，等价于同时发生的概率是乘积。不要与互斥混淆：互斥事件高度相关。`,
      a: [Y(R`P(A \cap B) = P(A)\,P(B) \iff P(A \mid B) = P(A)`, { s: 22 }), W('independent ≠ incompatible|indépendants ≠ incompatibles|independientes ≠ incompatibles|独立 ≠ 排反|独立 ≠ 互斥', { c: 'p' })] },
    { s: R`$P(A) = 0.5$, $P(B) = 0.4$, $P(A \cap B) = 0.2$: since $0.5\cdot 0.4 = 0.2$, they are independent. With $P(A \cap B) = 0.3$ they would not be.|$P(A) = 0{,}5$, $P(B) = 0{,}4$, $P(A \cap B) = 0{,}2$ : comme $0{,}5\cdot 0{,}4 = 0{,}2$, ils sont indépendants.|$P(A) = 0{,}5$, $P(B) = 0{,}4$, $P(A \cap B) = 0{,}2$: como $0{,}5\cdot 0{,}4 = 0{,}2$, son independientes.|$0.5\cdot 0.4 = 0.2 = P(A \cap B)$ なので独立。|$0.5\cdot 0.4 = 0.2 = P(A \cap B)$，所以独立。`,
      a: [Y(R`0.5\cdot 0.4 = 0.2 = P(A \cap B)\ \checkmark`)] },
    { a: [F(R`P(A) = 0.3,\ P(B) = 0.6,\ \text{independent}`)],
      ex: { k: 'val', v: '0.72', q: R`$A$ and $B$ are independent with $P(A) = 0.3$ and $P(B) = 0.6$. Find $P(A \cup B)$.|$A$ et $B$ sont indépendants avec $P(A) = 0{,}3$ et $P(B) = 0{,}6$. Calculez $P(A \cup B)$.|$A$ y $B$ son independientes con $P(A) = 0{,}3$ y $P(B) = 0{,}6$. Halla $P(A \cup B)$.|$A$, $B$ は独立で $P(A) = 0.3$, $P(B) = 0.6$。$P(A \cup B)$ を求めよ。|$A$、$B$ 独立，$P(A) = 0.3$，$P(B) = 0.6$，求 $P(A \cup B)$。`,
        sol: [R`P(A \cap B) = 0.3\cdot 0.6 = 0.18`, R`0.3 + 0.6 - 0.18 = 0.72`] } });

  lesson('Conditional probability/Total probability', 'The law of total probability|Formule des probabilités totales|Teorema de la probabilidad total|全確率の公式|全概率公式',
    { s: R`Split the world into cases $B_1, B_2, \dots$ that cover everything and do not overlap. The chance of $A$ is the sum over the cases: probability of the case times probability of $A$ in that case — the branches of a tree.|On découpe l’univers en cas $B_1, B_2, \dots$ qui recouvrent tout sans se chevaucher. La probabilité de $A$ est la somme sur les cas : probabilité du cas fois probabilité de $A$ dans ce cas — les branches d’un arbre.|Divide el universo en casos $B_1, B_2, \dots$ que lo cubren todo sin solaparse. La probabilidad de $A$ es la suma sobre los casos: probabilidad del caso por probabilidad de $A$ en ese caso, las ramas de un árbol.|全体を重ならずにすべてを覆う場合 $B_1, B_2, \dots$ に分ける。$A$ の確率は各場合の「場合の確率 × その場合での $A$ の確率」の和（樹形図の枝）。|把样本空间分成互不重叠且覆盖全部的情形 $B_1, B_2, \dots$。$A$ 的概率是各情形“情形概率 × 该情形下 $A$ 的概率”之和——树形图的分支。`,
      a: [Y(R`P(A) = \sum_i P(A \mid B_i)\,P(B_i)`), ...TREE('0.6', '0.02', '0.05', ['M₁', 'M₂'], ['D', 'D̄'])] },
    { s: R`Machine $M_1$ makes 60% of the parts with 2% defective; $M_2$ makes 40% with 5% defective. $P(D) = 0.6\cdot 0.02 + 0.4\cdot 0.05 = 0.012 + 0.02 = 0.032$.|La machine $M_1$ fait 60 % des pièces, dont 2 % défectueuses ; $M_2$ en fait 40 %, dont 5 % défectueuses. $P(D) = 0{,}6\cdot 0{,}02 + 0{,}4\cdot 0{,}05 = 0{,}032$.|La máquina $M_1$ hace el 60 % de las piezas con un 2 % defectuosas; $M_2$ el 40 % con un 5 %. $P(D) = 0{,}6\cdot 0{,}02 + 0{,}4\cdot 0{,}05 = 0{,}032$.|機械 $M_1$ が 60%（不良率 2%）、$M_2$ が 40%（不良率 5%）。$P(D) = 0.012 + 0.02 = 0.032$。|机器 $M_1$ 生产 60%（次品率 2%），$M_2$ 生产 40%（次品率 5%）。$P(D) = 0.012 + 0.02 = 0.032$。`,
      a: [F(R`P(D) = 0.6\cdot 0.02 + 0.4\cdot 0.05`), Y(R`= 0.032`), ...TREE('0.6', '0.02', '0.05', ['M₁', 'M₂'], ['D', 'D̄'])] },
    { a: [F(R`\text{heads} \to U_1(3R, 2W),\quad \text{tails} \to U_2(1R, 4W)`, { s: 22 }), ...TREE('½', '3/5', '1/5', ['U₁', 'U₂'], ['R', 'W'])],
      ex: { k: 'val', v: '2/5', q: R`Toss a coin: heads, draw from urn 1 (3 red, 2 white); tails, from urn 2 (1 red, 4 white). Find $P(\text{red})$.|On lance une pièce : face, on tire dans l’urne 1 (3 rouges, 2 blanches) ; pile, dans l’urne 2 (1 rouge, 4 blanches). Calculez $P(\text{rouge})$.|Se lanza una moneda: cara, se saca de la urna 1 (3 rojas, 2 blancas); cruz, de la urna 2 (1 roja, 4 blancas). Halla $P(\text{roja})$.|硬貨を投げ、表なら袋 1（赤 3・白 2）、裏なら袋 2（赤 1・白 4）から 1 個取る。$P(\text{赤})$ を求めよ。|掷硬币：正面从袋 1（3 红 2 白）取，反面从袋 2（1 红 4 白）取，求 $P(\text{红})$。`,
        sol: [R`\tfrac12\cdot\tfrac35 + \tfrac12\cdot\tfrac15`, R`= \tfrac{3}{10} + \tfrac{1}{10} = \tfrac25`] } });

  lesson('Conditional probability/Bayes’ theorem', 'Bayes’ theorem|Formule de Bayes|Teorema de Bayes|ベイズの定理|贝叶斯公式',
    { s: R`Bayes turns the question around: from “chance of the effect given the cause” to “chance of the cause given the effect”. The numerator is one path of the tree; the denominator is all paths leading to the observed effect (total probability).|Bayes retourne la question : de « probabilité de l’effet sachant la cause » à « probabilité de la cause sachant l’effet ». Le numérateur est un chemin de l’arbre ; le dénominateur, tous les chemins menant à l’effet observé (probabilités totales).|Bayes da la vuelta a la pregunta: de «probabilidad del efecto dada la causa» a «probabilidad de la causa dado el efecto». El numerador es una rama del árbol; el denominador, todas las ramas que llevan al efecto observado (probabilidad total).|ベイズは問いを逆にする：「原因のもとでの結果」から「結果のもとでの原因」へ。分子は樹形図の 1 本の道、分母は観測された結果に至るすべての道（全確率）。|贝叶斯把问题倒过来：从“已知原因求结果的概率”到“已知结果求原因的概率”。分子是树上的一条路径；分母是通向所观测结果的所有路径（全概率）。`,
      a: [Y(R`P(B \mid A) = \frac{P(A \mid B)\,P(B)}{P(A)}`), W('one path / all paths to A|un chemin / tous les chemins vers A|una rama / todas las ramas hacia A|1 本の道 / A へのすべての道|一条路径 / 通向 A 的所有路径')] },
    { s: R`Same factory: a part is defective. Which machine made it? $P(M_2 \mid D) = \tfrac{0.4\cdot 0.05}{0.032} = \tfrac{0.02}{0.032} = 0.625$ — the worse machine is more likely, although it makes fewer parts.|Même usine : une pièce est défectueuse. Quelle machine l’a faite ? $P(M_2 \mid D) = \tfrac{0{,}02}{0{,}032} = 0{,}625$ — la moins bonne machine est la plus probable, bien qu’elle produise moins.|Misma fábrica: una pieza es defectuosa. ¿Qué máquina la hizo? $P(M_2 \mid D) = \tfrac{0{,}02}{0{,}032} = 0{,}625$: la peor máquina es más probable, aunque fabrique menos.|同じ工場で不良品が出た。$P(M_2 \mid D) = \tfrac{0.02}{0.032} = 0.625$（生産量は少ないが不良率の高い機械の方が有力）。|同一工厂出现次品，$P(M_2 \mid D) = \tfrac{0.02}{0.032} = 0.625$——较差的机器可能性更大，尽管它产量少。`,
      a: [F(R`P(M_2 \mid D) = \frac{0.4\cdot 0.05}{0.032}`), Y(R`= 0.625`), ...TREE('0.6', '0.02', '0.05', ['M₁', 'M₂'], ['D', 'D̄'])] },
    { a: [F(R`P(D) = 0.01,\ P(+ \mid D) = 0.99,\ P(+ \mid \bar D) = 0.05`, { s: 22 }), ...TREE('0.01', '0.99', '0.05', ['D', 'D̄'], ['+', '−'])],
      ex: { k: 'val', v: '1/6', q: R`A disease affects 1% of people. A test is positive for 99% of the sick and for 5% of the healthy. Someone tests positive: what is the probability that they are sick?|Une maladie touche 1 % des gens. Un test est positif pour 99 % des malades et 5 % des sains. Une personne est positive : quelle est la probabilité qu’elle soit malade ?|Una enfermedad afecta al 1 %. Un test da positivo en el 99 % de los enfermos y en el 5 % de los sanos. Alguien da positivo: ¿probabilidad de que esté enfermo?|ある病気の有病率は 1%。検査は患者の 99%、健康な人の 5% で陽性。陽性だった人が病気である確率を求めよ。|某病患病率 1%，检测对 99% 的病人和 5% 的健康人呈阳性。某人阳性，求其患病的概率。`,
        sol: [R`P(+) = 0.01\cdot 0.99 + 0.99\cdot 0.05 = 0.0594`, R`P(D \mid +) = \frac{0.0099}{0.0594}`, R`= \frac16 \approx 0.167`] } });

  // =============================== Random variables ===============================
  const XP = [0.2, 0.5, 0.3];
  lesson('Random variables/Expectation', 'Expectation|Espérance|Esperanza|期待値|数学期望',
    { s: R`The expectation is the long-run average: each value weighted by its probability. On the bar chart it is the balance point. In games, $E > 0$ means you win on average.|L’espérance est la moyenne à long terme : chaque valeur pondérée par sa probabilité. Sur le diagramme en barres, c’est le point d’équilibre. Dans un jeu, $E > 0$ signifie qu’on gagne en moyenne.|La esperanza es el promedio a largo plazo: cada valor ponderado por su probabilidad. En el diagrama de barras es el punto de equilibrio. En un juego, $E > 0$ significa que se gana en promedio.|期待値は長い目で見た平均：各値を確率で重みづけ。棒グラフの釣り合いの点。ゲームでは $E > 0$ なら平均して得。|期望是长期平均：每个值按概率加权。在条形图上它是平衡点。游戏中 $E > 0$ 表示平均会赢。`,
      a: [Y(R`E[X] = \sum x_i\,p_i`, { s: 30 }), S2([1, 0.5], 1.6, true), ...BARS(XP, 0, 2), PT([1.1, 0], 'E = 1.1', 'o', { dy: 22, dx: -20 })] },
    { s: R`A game: win 10 with probability 0.2, lose 2 otherwise. $E = 10\cdot 0.2 + (-2)\cdot 0.8 = 2 - 1.6 = 0.4$: on average you gain 0.4 per game.|Un jeu : on gagne 10 avec la probabilité 0,2, sinon on perd 2. $E = 10\cdot 0{,}2 - 2\cdot 0{,}8 = 0{,}4$ : en moyenne on gagne 0,4 par partie.|Un juego: ganas 10 con probabilidad 0,2 y si no pierdes 2. $E = 10\cdot 0{,}2 - 2\cdot 0{,}8 = 0{,}4$: de media ganas 0,4 por partida.|確率 0.2 で 10 得、それ以外 2 失う：$E = 2 - 1.6 = 0.4$。|以 0.2 的概率赢 10，否则输 2：$E = 2 - 1.6 = 0.4$。`,
      a: [F(R`E = 10\cdot 0.2 + (-2)\cdot 0.8`), Y(R`= 0.4`)] },
    { a: [F(R`x:\ 0,\ 1,\ 2\quad p:\ 0.2,\ 0.5,\ 0.3`), S2([1, 0.5], 1.6, true), ...BARS(XP, 0, 2)],
      ex: { k: 'val', v: '1.1', q: R`$X$ takes the values 0, 1, 2 with probabilities 0.2, 0.5, 0.3. Find $E[X]$.|$X$ prend les valeurs 0, 1, 2 avec les probabilités 0,2 ; 0,5 ; 0,3. Calculez $E[X]$.|$X$ toma los valores 0, 1, 2 con probabilidades 0,2; 0,5; 0,3. Halla $E[X]$.|$X$ は 0, 1, 2 を確率 0.2, 0.5, 0.3 でとる。$E[X]$ を求めよ。|$X$ 取 0, 1, 2 的概率为 0.2, 0.5, 0.3，求 $E[X]$。`,
        sol: [R`0\cdot 0.2 + 1\cdot 0.5 + 2\cdot 0.3`, R`= 1.1`] } });

  lesson('Random variables/Variance', 'Variance and standard deviation|Variance et écart-type|Varianza y desviación típica|分散と標準偏差|方差与标准差',
    { s: R`The variance measures spread: the average squared distance from the mean. The shortcut “mean of the squares minus square of the mean” is usually faster. The standard deviation $\sigma$ is its square root, back in the units of $X$.|La variance mesure la dispersion : la moyenne des carrés des écarts à la moyenne. Le raccourci « moyenne des carrés moins carré de la moyenne » est souvent plus rapide. L’écart-type $\sigma$ en est la racine, dans l’unité de $X$.|La varianza mide la dispersión: la media de las distancias al cuadrado a la media. El atajo «media de los cuadrados menos el cuadrado de la media» suele ser más rápido. La desviación típica $\sigma$ es su raíz, en las unidades de $X$.|分散はばらつき：平均からの距離の 2 乗の平均。「2 乗の平均 − 平均の 2 乗」の方が速い。標準偏差 $\sigma$ はその平方根（$X$ と同じ単位）。|方差衡量离散程度：与均值距离平方的平均。捷径“平方的均值减均值的平方”通常更快。标准差 $\sigma$ 是它的平方根，单位与 $X$ 相同。`,
      a: [Y(R`\operatorname{Var}X = E[X^2] - E[X]^2`), F(R`\sigma = \sqrt{\operatorname{Var}X}`)] },
    { s: R`For $X$ = 0, 1, 2 with $p$ = 0.2, 0.5, 0.3: $E[X] = 1.1$, $E[X^2] = 0 + 0.5 + 1.2 = 1.7$, so $\operatorname{Var}X = 1.7 - 1.21 = 0.49$ and $\sigma = 0.7$.|Pour $X$ = 0, 1, 2 avec $p$ = 0,2 ; 0,5 ; 0,3 : $E[X] = 1{,}1$, $E[X^2] = 1{,}7$, donc $\operatorname{Var}X = 1{,}7 - 1{,}21 = 0{,}49$ et $\sigma = 0{,}7$.|Para $X$ = 0, 1, 2 con $p$ = 0,2; 0,5; 0,3: $E[X] = 1{,}1$, $E[X^2] = 1{,}7$, así que $\operatorname{Var}X = 0{,}49$ y $\sigma = 0{,}7$.|$E[X] = 1.1$, $E[X^2] = 1.7$ で $\operatorname{Var}X = 0.49$、$\sigma = 0.7$。|$E[X] = 1.1$，$E[X^2] = 1.7$，$\operatorname{Var}X = 0.49$，$\sigma = 0.7$。`,
      a: [F(R`E[X^2] = 0\cdot 0.2 + 1\cdot 0.5 + 4\cdot 0.3 = 1.7`), Y(R`\operatorname{Var}X = 1.7 - 1.1^2 = 0.49,\quad \sigma = 0.7`)] },
    { a: [F(R`x:\ -1,\ 0,\ 2\quad p:\ 0.25,\ 0.25,\ 0.5`)],
      ex: { k: 'val', v: '27/16', q: R`$X$ takes the values $-1$, 0, 2 with probabilities 0.25, 0.25, 0.5. Find $\operatorname{Var}X$.|$X$ prend les valeurs $-1$, 0, 2 avec les probabilités 0,25 ; 0,25 ; 0,5. Calculez $\operatorname{Var}X$.|$X$ toma los valores $-1$, 0, 2 con probabilidades 0,25; 0,25; 0,5. Halla $\operatorname{Var}X$.|$X$ は $-1$, 0, 2 を確率 0.25, 0.25, 0.5 でとる。$\operatorname{Var}X$ を求めよ。|$X$ 取 $-1$, 0, 2 的概率为 0.25, 0.25, 0.5，求 $\operatorname{Var}X$。`,
        sol: [R`E[X] = -0.25 + 1 = 0.75`, R`E[X^2] = 0.25 + 2 = 2.25`, R`\operatorname{Var}X = 2.25 - 0.5625 = 1.6875 = \tfrac{27}{16}`] } });

  lesson('Random variables/Linear change', 'Linear change of a variable|Transformation affine|Cambio lineal|1 次変換|线性变换',
    { s: R`Shifting by $b$ moves the mean but not the spread; scaling by $a$ multiplies the mean by $a$ and the variance by $a^2$ (the standard deviation by $\lvert a\rvert$). A sign change does not reduce the spread.|Ajouter $b$ décale la moyenne sans changer la dispersion ; multiplier par $a$ multiplie la moyenne par $a$ et la variance par $a^2$ (l’écart-type par $\lvert a\rvert$). Un changement de signe ne réduit pas la dispersion.|Sumar $b$ mueve la media pero no la dispersión; multiplicar por $a$ multiplica la media por $a$ y la varianza por $a^2$ (la desviación por $\lvert a\rvert$). Cambiar el signo no reduce la dispersión.|$b$ を足すと平均は動くがばらつきは同じ。$a$ 倍すると平均は $a$ 倍、分散は $a^2$ 倍（標準偏差は $\lvert a\rvert$ 倍）。符号を変えてもばらつきは減らない。|加 $b$ 改变均值不改变离散；乘 $a$ 使均值乘 $a$、方差乘 $a^2$（标准差乘 $\lvert a\rvert$）。变号不会减小离散程度。`,
      a: [Y(R`E[aX + b] = aE[X] + b`), Y(R`\operatorname{Var}(aX + b) = a^2\operatorname{Var}X`)] },
    { s: R`$E[X] = 3$, $\operatorname{Var}X = 4$, $Y = 2X + 1$: $E[Y] = 7$ and $\operatorname{Var}Y = 4\cdot 4 = 16$ — the $+1$ does not matter for the variance.|$E[X] = 3$, $\operatorname{Var}X = 4$, $Y = 2X + 1$ : $E[Y] = 7$ et $\operatorname{Var}Y = 16$ — le $+1$ n’agit pas sur la variance.|$E[X] = 3$, $\operatorname{Var}X = 4$, $Y = 2X + 1$: $E[Y] = 7$ y $\operatorname{Var}Y = 16$; el $+1$ no afecta a la varianza.|$E[Y] = 7$、$\operatorname{Var}Y = 16$（$+1$ は分散に影響しない）。|$E[Y] = 7$，$\operatorname{Var}Y = 16$（$+1$ 不影响方差）。`,
      a: [F(R`E[2X + 1] = 2\cdot 3 + 1 = 7`), Y(R`\operatorname{Var}(2X + 1) = 4\cdot 4 = 16`)] },
    { a: [F(R`E[X] = 5,\ \sigma_X = 2,\ Y = 3 - 2X`)],
      ex: { k: 'val', v: '4', q: R`$E[X] = 5$ and $\sigma_X = 2$. Find the standard deviation of $Y = 3 - 2X$.|$E[X] = 5$ et $\sigma_X = 2$. Calculez l’écart-type de $Y = 3 - 2X$.|$E[X] = 5$ y $\sigma_X = 2$. Halla la desviación típica de $Y = 3 - 2X$.|$E[X] = 5$, $\sigma_X = 2$。$Y = 3 - 2X$ の標準偏差を求めよ。|$E[X] = 5$，$\sigma_X = 2$，求 $Y = 3 - 2X$ 的标准差。`,
        sol: [R`\operatorname{Var}Y = (-2)^2\cdot 4 = 16`, R`\sigma_Y = 4`] } });

  lesson('Random variables/Sums', 'Sums of random variables|Somme de variables aléatoires|Suma de variables aleatorias|確率変数の和|随机变量之和',
    { s: R`Expectations always add, even for dependent variables. Variances add only for independent variables. That is why the mean of many dice grows like $n$ while their spread grows only like $\sqrt n$.|Les espérances s’ajoutent toujours, même pour des variables dépendantes. Les variances ne s’ajoutent que pour des variables indépendantes. C’est pourquoi la somme de $n$ dés a une moyenne en $n$ mais un écart-type en $\sqrt n$ seulement.|Las esperanzas siempre se suman, incluso para variables dependientes. Las varianzas solo se suman si son independientes. Por eso la suma de $n$ dados tiene media proporcional a $n$ pero dispersión solo como $\sqrt n$.|期待値は従属でも常に足せる。分散は独立なときだけ足せる。だから $n$ 個のさいころの和は平均が $n$ に比例、標準偏差は $\sqrt n$ にしか比例しない。|期望总可以相加，即使变量相关。方差只有独立时才相加。所以 $n$ 颗骰子之和均值随 $n$ 增长，标准差只随 $\sqrt n$ 增长。`,
      a: [Y(R`E[X + Y] = E[X] + E[Y]`), F(R`\text{independent:}\ \operatorname{Var}(X + Y) = \operatorname{Var}X + \operatorname{Var}Y`, { s: 22 }), S2([7, 0.1], 6.2, true), ...BARS([1, 2, 3, 4, 5, 6, 5, 4, 3, 2, 1].map(v => v / 36), 2, 25)] },
    { s: R`Sum of two dice: $E = 3.5 + 3.5 = 7$, and since they are independent $\operatorname{Var} = \tfrac{35}{12} + \tfrac{35}{12} = \tfrac{35}{6}$. The bar chart peaks at 7.|Somme de deux dés : $E = 3{,}5 + 3{,}5 = 7$ et, les dés étant indépendants, $\operatorname{Var} = \tfrac{35}{6}$. Le diagramme culmine en 7.|Suma de dos dados: $E = 3{,}5 + 3{,}5 = 7$ y, al ser independientes, $\operatorname{Var} = \tfrac{35}{6}$. El diagrama tiene su máximo en 7.|2 個のさいころの和：$E = 7$、独立なので $\operatorname{Var} = \tfrac{35}{6}$。|两颗骰子之和：$E = 7$，独立故 $\operatorname{Var} = \tfrac{35}{6}$。`,
      a: [F(R`E = 3.5 + 3.5 = 7`), Y(R`\operatorname{Var} = \tfrac{35}{12} + \tfrac{35}{12} = \tfrac{35}{6}`)] },
    { a: [F(R`X_1 + \dots + X_{10}`)],
      ex: { k: 'val', v: '35', q: R`Ten fair dice are rolled. What is the expected value of their sum?|On lance dix dés équilibrés. Quelle est l’espérance de leur somme ?|Se lanzan diez dados equilibrados. ¿Cuál es la esperanza de su suma?|公正なさいころを 10 個投げる。目の和の期待値を求めよ。|掷 10 颗均匀骰子，点数和的期望是多少？`,
        sol: [R`E[X_i] = 3.5`, R`E[\Sigma] = 10\cdot 3.5 = 35`] } });

  lesson('Random variables/One fair die', 'One fair die|Un dé équilibré|Un dado equilibrado|公正なさいころ 1 個|一颗均匀骰子',
    { s: R`Each face has probability $\tfrac16$. The mean is the middle of 1 and 6, $3.5$ (never an actual roll!). $E[X^2] = \tfrac{1 + 4 + 9 + 16 + 25 + 36}{6} = \tfrac{91}{6}$, so $\operatorname{Var} = \tfrac{91}{6} - 3.5^2 = \tfrac{35}{12}$.|Chaque face a la probabilité $\tfrac16$. La moyenne est le milieu de 1 et 6, $3{,}5$ (jamais obtenu !). $E[X^2] = \tfrac{91}{6}$, donc $\operatorname{Var} = \tfrac{91}{6} - 3{,}5^2 = \tfrac{35}{12}$.|Cada cara tiene probabilidad $\tfrac16$. La media es el punto medio de 1 y 6, $3{,}5$ (¡nunca sale!). $E[X^2] = \tfrac{91}{6}$, así que $\operatorname{Var} = \tfrac{91}{6} - 3{,}5^2 = \tfrac{35}{12}$.|各目の確率は $\tfrac16$。平均は 3.5（実際には出ない）。$E[X^2] = \tfrac{91}{6}$ で $\operatorname{Var} = \tfrac{35}{12}$。|每面概率 $\tfrac16$。均值是 3.5（永远掷不出！）。$E[X^2] = \tfrac{91}{6}$，$\operatorname{Var} = \tfrac{35}{12}$。`,
      a: [Y(R`E = 3.5,\quad \operatorname{Var} = \frac{35}{12}`), S2([3.5, 0.3], 3.6, true), ...BARS([1, 1, 1, 1, 1, 1].map(() => 1 / 6), 1, 4), PT([3.5, 0], '3.5', 'o')] },
    { s: R`Win as many euros as the die shows, paying 4 to play: the gain is $X - 4$, so $E = 3.5 - 4 = -0.5$ — on average you lose 50 cents a game.|On gagne autant d’euros que le dé indique, et on paie 4 pour jouer : le gain est $X - 4$, $E = -0{,}5$ — on perd 50 centimes par partie en moyenne.|Ganas tantos euros como marca el dado y pagas 4 por jugar: la ganancia es $X - 4$, $E = -0{,}5$: de media pierdes 50 céntimos por partida.|出た目の数だけもらい、参加費 4：$E = 3.5 - 4 = -0.5$。|赢得骰子点数的钱，每局付 4：$E = 3.5 - 4 = -0.5$。`,
      a: [Y(R`E[X - 4] = 3.5 - 4 = -0.5`)] },
    { a: [F(R`X:\ \text{one fair die}`)],
      ex: { k: 'val', v: '91/6', q: R`For one fair die, compute $E[X^2]$.|Pour un dé équilibré, calculez $E[X^2]$.|Para un dado equilibrado, calcula $E[X^2]$.|公正なさいころ 1 個について $E[X^2]$ を求めよ。|对一颗均匀骰子，求 $E[X^2]$。`,
        sol: [R`\frac{1 + 4 + 9 + 16 + 25 + 36}{6}`, R`= \frac{91}{6}`] } });

  // =============================== Distributions ===============================
  lesson('Distributions/Binomial B(n, p)', 'Binomial distribution|Loi binomiale|Distribución binomial|二項分布|二项分布',
    { s: R`$n$ independent trials, each a success with probability $p$. Exactly $k$ successes: choose which $k$ trials succeed ($\binom nk$ ways), times $p^k$ for them and $(1 - p)^{n-k}$ for the others. On average $np$ successes.|$n$ épreuves indépendantes, chacune réussie avec la probabilité $p$. Exactement $k$ succès : on choisit lesquelles réussissent ($\binom nk$ façons), fois $p^k$ pour elles et $(1 - p)^{n-k}$ pour les autres. En moyenne $np$ succès.|$n$ pruebas independientes, cada una con probabilidad de éxito $p$. Exactamente $k$ éxitos: elige qué $k$ pruebas aciertan ($\binom nk$ formas), por $p^k$ para ellas y $(1 - p)^{n-k}$ para las demás. En promedio, $np$ éxitos.|独立な $n$ 回の試行、各回の成功確率 $p$。ちょうど $k$ 回成功：どの $k$ 回か（$\binom nk$ 通り）× $p^k$ × $(1 - p)^{n-k}$。平均 $np$ 回。|$n$ 次独立试验，每次成功概率 $p$。恰 $k$ 次成功：选出哪 $k$ 次（$\binom nk$ 种），乘以 $p^k$ 和 $(1 - p)^{n-k}$。平均 $np$ 次。`,
      a: [Y(R`P(X = k) = \binom nk p^k(1 - p)^{n-k}`), F(R`E = np,\quad \operatorname{Var} = np(1 - p)`), S2([5, 1.4], 5.5, true), ...BARS(binom(10, 0.5), 0, 12, 'b', 5)] },
    { s: R`A die rolled 4 times, exactly two sixes: $\binom42\left(\tfrac16\right)^2\left(\tfrac56\right)^2 = 6\cdot\tfrac{25}{1296} \approx 0.116$.|Un dé lancé 4 fois, exactement deux six : $\binom42\left(\tfrac16\right)^2\left(\tfrac56\right)^2 \approx 0{,}116$.|Un dado lanzado 4 veces, exactamente dos seises: $\binom42\left(\tfrac16\right)^2\left(\tfrac56\right)^2 \approx 0{,}116$.|さいころ 4 回でちょうど 2 回 6：$\binom42\left(\tfrac16\right)^2\left(\tfrac56\right)^2 \approx 0.116$。|掷骰子 4 次恰两次 6 点：$\binom42\left(\tfrac16\right)^2\left(\tfrac56\right)^2 \approx 0.116$。`,
      a: [F(R`\binom42\left(\tfrac16\right)^2\left(\tfrac56\right)^2 = 6\cdot\frac{25}{1296}`), Y(R`\approx 0.116`), S2([2, 0.3], 2.6, true), ...BARS(binom(4, 1 / 6), 0, 3, 'b', 2)] },
    { a: [F(R`X \sim B(5, \tfrac12)`), S2([2.5, 0.4], 3.2, true), ...BARS(binom(5, 0.5), 0, 5)],
      ex: { k: 'val', v: '5/16', q: R`Five fair coins are tossed. Find the probability of exactly 3 heads.|On lance cinq pièces équilibrées. Calculez la probabilité d’obtenir exactement 3 faces.|Se lanzan cinco monedas equilibradas. Halla la probabilidad de exactamente 3 caras.|公正な硬貨を 5 枚投げる。ちょうど 3 枚表になる確率を求めよ。|掷 5 枚均匀硬币，求恰好 3 个正面的概率。`,
        sol: [R`\binom53\left(\tfrac12\right)^5 = \frac{10}{32}`, R`= \frac{5}{16}`] } });

  lesson('Distributions/Geometric', 'Geometric distribution|Loi géométrique|Distribución geométrica|幾何分布|几何分布',
    { s: R`Repeat a trial until the first success: $k - 1$ failures, then a success. The probabilities shrink by the factor $1 - p$ each time. The mean waiting time is $\tfrac1p$: 6 rolls on average to see a six.|On répète une épreuve jusqu’au premier succès : $k - 1$ échecs puis un succès. Les probabilités diminuent du facteur $1 - p$ à chaque fois. L’attente moyenne est $\tfrac1p$ : 6 lancers en moyenne pour un six.|Se repite una prueba hasta el primer éxito: $k - 1$ fracasos y un éxito. Las probabilidades bajan por el factor $1 - p$ cada vez. La espera media es $\tfrac1p$: 6 tiradas de media para un seis.|最初の成功まで繰り返す：$k - 1$ 回失敗して成功。確率は毎回 $1 - p$ 倍に減る。平均の待ち回数は $\tfrac1p$（6 が出るまで平均 6 回）。|重复试验直到首次成功：$k - 1$ 次失败后成功。概率每次乘以 $1 - p$。平均等待次数 $\tfrac1p$：平均掷 6 次出现 6 点。`,
      a: [Y(R`P(X = k) = (1 - p)^{k-1}p,\quad E = \frac1p`), S2([4.5, 0.4], 4.6, true), ...BARS([...Array(9)].map((_, k) => (5 / 6) ** k / 6), 1, 4)] },
    { s: R`First six on the 3rd roll: two failures then a success, $\left(\tfrac56\right)^2\cdot\tfrac16 = \tfrac{25}{216} \approx 0.116$.|Premier six au 3e lancer : deux échecs puis un succès, $\left(\tfrac56\right)^2\cdot\tfrac16 = \tfrac{25}{216}$.|Primer seis en la 3.ª tirada: dos fracasos y un éxito, $\left(\tfrac56\right)^2\cdot\tfrac16 = \tfrac{25}{216}$.|3 回目に初めて 6：$\left(\tfrac56\right)^2\cdot\tfrac16 = \tfrac{25}{216}$。|第 3 次首次出现 6：$\left(\tfrac56\right)^2\cdot\tfrac16 = \tfrac{25}{216}$。`,
      a: [Y(R`P(X = 3) = \left(\tfrac56\right)^2\cdot\tfrac16 = \tfrac{25}{216}`)] },
    { a: [F(R`p = 0.3`)],
      ex: { k: 'val', v: '0.1029', q: R`A trial succeeds with probability 0.3. Find the probability that the first success comes on the 4th trial.|Une épreuve réussit avec la probabilité 0,3. Calculez la probabilité que le premier succès ait lieu à la 4e épreuve.|Una prueba tiene éxito con probabilidad 0,3. Halla la probabilidad de que el primer éxito sea en la 4.ª prueba.|成功確率 0.3 の試行で、初めての成功が 4 回目となる確率を求めよ。|每次成功概率 0.3，求首次成功出现在第 4 次的概率。`,
        sol: [R`0.7^3\cdot 0.3`, R`= 0.343\cdot 0.3 = 0.1029`] } });

  lesson('Distributions/Uniform on {1, …, n}', 'Discrete uniform distribution|Loi uniforme discrète|Distribución uniforme discreta|離散一様分布|离散均匀分布',
    { s: R`Every value $1, \dots, n$ is equally likely, like a fair die with $n$ faces. The mean is the middle, $\tfrac{n + 1}{2}$. Probabilities of events are counts divided by $n$.|Chaque valeur $1, \dots, n$ a la même probabilité, comme un dé équilibré à $n$ faces. La moyenne est le milieu, $\tfrac{n + 1}{2}$. La probabilité d’un événement est un nombre de valeurs divisé par $n$.|Cada valor $1, \dots, n$ es igual de probable, como un dado de $n$ caras. La media es el centro, $\tfrac{n + 1}{2}$. La probabilidad de un suceso es un recuento dividido entre $n$.|$1, \dots, n$ が同じ確率（$n$ 面のさいころ）。平均は真ん中 $\tfrac{n + 1}{2}$。事象の確率は個数 ÷ $n$。|$1, \dots, n$ 每个值等可能，像 $n$ 面骰子。均值在中间 $\tfrac{n + 1}{2}$。事件概率为个数除以 $n$。`,
      a: [Y(R`P(X = k) = \frac1n,\quad E = \frac{n + 1}{2}`), S2([5.5, 0.4], 5.2, true), ...BARS([...Array(10)].map(() => 0.1), 1, 4)] },
    { s: R`A random integer from 1 to 10: $E = 5.5$; $P(\text{prime}) = \tfrac{4}{10}$ (2, 3, 5, 7).|Un entier au hasard de 1 à 10 : $E = 5{,}5$ ; $P(\text{premier}) = \tfrac{4}{10}$ (2, 3, 5, 7).|Un entero al azar de 1 a 10: $E = 5{,}5$; $P(\text{primo}) = \tfrac{4}{10}$ (2, 3, 5, 7).|1〜10 の整数：$E = 5.5$、$P(\text{素数}) = \tfrac{4}{10}$。|1 到 10 的随机整数：$E = 5.5$，$P(\text{素数}) = \tfrac{4}{10}$。`,
      a: [F(R`E = \frac{10 + 1}{2} = 5.5`), Y(R`P(\{2, 3, 5, 7\}) = \frac{4}{10}`)] },
    { a: [F(R`X \in \{1, \dots, 20\}`)],
      ex: { k: 'val', v: '0.3', q: R`An integer is chosen at random from 1 to 20. Find the probability that it is a multiple of 3.|On choisit un entier au hasard de 1 à 20. Calculez la probabilité que ce soit un multiple de 3.|Se elige un entero al azar de 1 a 20. Halla la probabilidad de que sea múltiplo de 3.|1 から 20 の整数を 1 つ選ぶ。3 の倍数である確率を求めよ。|从 1 到 20 随机取一个整数，求它是 3 的倍数的概率。`,
        sol: [R`3, 6, \dots, 18:\ 6\ \text{values}`, R`\frac{6}{20} = 0.3`] } });

  lesson('Distributions/Normal N(μ, σ²)', 'Normal distribution|Loi normale|Distribución normal|正規分布|正态分布',
    { s: R`The bell curve, centred at $\mu$, with width $\sigma$. Every normal becomes the standard one by measuring “how many $\sigma$ away from $\mu$”: $Z = \tfrac{X - \mu}\sigma$. Rough rule: 68% within one $\sigma$, 95% within two, 99.7% within three.|La courbe en cloche, centrée en $\mu$, de largeur $\sigma$. Toute loi normale se ramène à la loi centrée réduite en mesurant « à combien de $\sigma$ de $\mu$ » : $Z = \tfrac{X - \mu}\sigma$. Règle : 68 % à moins d’un $\sigma$, 95 % à deux, 99,7 % à trois.|La campana, centrada en $\mu$ y de anchura $\sigma$. Toda normal pasa a la estándar midiendo «a cuántas $\sigma$ de $\mu$»: $Z = \tfrac{X - \mu}\sigma$. Regla: 68 % a menos de una $\sigma$, 95 % a dos, 99,7 % a tres.|$\mu$ を中心、幅 $\sigma$ のベル曲線。「$\mu$ から何 $\sigma$ 離れているか」$Z = \tfrac{X - \mu}\sigma$ で標準正規分布に。目安：$1\sigma$ 以内 68%、$2\sigma$ 95%、$3\sigma$ 99.7%。|以 $\mu$ 为中心、宽度为 $\sigma$ 的钟形曲线。用“离 $\mu$ 几个 $\sigma$”即 $Z = \tfrac{X - \mu}\sigma$ 化为标准正态。经验：$1\sigma$ 内 68%，$2\sigma$ 内 95%，$3\sigma$ 内 99.7%。`,
      a: [Y(R`Z = \frac{X - \mu}{\sigma} \sim N(0, 1)`), F(R`68\%,\ 95\%,\ 99.7\%`), AX([-4, 4], [-0.05, 0.5]), P(N01), SH(-2, 2)] },
    { s: R`Heights $N(170, 10^2)$: 180 cm is $z = 1$, so $P(X < 180) = \Phi(1) \approx 0.841$: about 84% are shorter.|Tailles $N(170, 10^2)$ : 180 cm correspond à $z = 1$, donc $P(X < 180) = \Phi(1) \approx 0{,}841$ : environ 84 % sont plus petits.|Estaturas $N(170, 10^2)$: 180 cm es $z = 1$, así que $P(X < 180) = \Phi(1) \approx 0{,}841$: un 84 % son más bajos.|身長 $N(170, 10^2)$：180 は $z = 1$、$\Phi(1) \approx 0.841$。|身高 $N(170, 10^2)$：180 对应 $z = 1$，$\Phi(1) \approx 0.841$。`,
      a: [F(R`z = \frac{180 - 170}{10} = 1`), Y(R`P(X < 180) = \Phi(1) \approx 0.841`), AX([-4, 4], [-0.05, 0.5]), P(N01), SH(-4, 1)] },
    { a: [F(R`X \sim N(100, 15^2)`), AX([-4, 4], [-0.05, 0.5]), P(N01)],
      ex: { k: 'val', v: '0.9545', q: R`IQ scores follow $N(100, 15^2)$. Estimate $P(70 < X < 130)$ with the 68–95–99.7 rule (or the table).|Le QI suit $N(100, 15^2)$. Estimez $P(70 < X < 130)$ avec la règle 68–95–99,7 (ou la table).|El CI sigue $N(100, 15^2)$. Estima $P(70 < X < 130)$ con la regla 68–95–99,7 (o la tabla).|IQ は $N(100, 15^2)$ に従う。68–95–99.7 の規則（または表）で $P(70 < X < 130)$ を求めよ。|智商服从 $N(100, 15^2)$，用 68–95–99.7 法则（或查表）估计 $P(70 < X < 130)$。`,
        sol: [R`z = \pm\frac{30}{15} = \pm 2`, R`P(-2 < Z < 2) \approx 0.95\ (0.9545)`] } });

  lesson('Distributions/Poisson', 'Poisson distribution|Loi de Poisson|Distribución de Poisson|ポアソン分布|泊松分布',
    { s: R`Counts of rare, independent events in a fixed time or space (calls per minute, typos per page), with average $\lambda$. Mean and variance are both $\lambda$. It is the limit of a binomial with large $n$ and small $p$, $\lambda = np$.|Nombre d’événements rares et indépendants sur une durée ou une zone fixée (appels par minute, fautes par page), de moyenne $\lambda$. Espérance et variance valent $\lambda$. C’est la limite d’une binomiale avec $n$ grand et $p$ petit, $\lambda = np$.|Recuento de sucesos raros e independientes en un tiempo o espacio fijo (llamadas por minuto, erratas por página), con media $\lambda$. Media y varianza valen $\lambda$. Es el límite de una binomial con $n$ grande y $p$ pequeño, $\lambda = np$.|一定の時間・範囲での稀で独立な出来事の回数（1 分あたりの電話、1 ページの誤字）。平均と分散はともに $\lambda$。$n$ 大・$p$ 小の二項分布の極限（$\lambda = np$）。|固定时间或空间内稀有独立事件的次数（每分钟来电、每页错字），均值 $\lambda$。期望与方差都等于 $\lambda$。是 $n$ 大 $p$ 小时二项分布的极限，$\lambda = np$。`,
      a: [Y(R`P(X = k) = e^{-\lambda}\frac{\lambda^k}{k!},\quad E = \operatorname{Var} = \lambda`, { s: 22 }), S2([4, 0.2], 4.4, true), ...BARS([0, 1, 2, 3, 4, 5, 6, 7, 8].map(k => Math.exp(-2) * 2 ** k / [1, 1, 2, 6, 24, 120, 720, 5040, 40320][k]), 0, 8)] },
    { s: R`On average 2 calls a minute: the chance of no call in a given minute is $e^{-2} \approx 0.135$, and of exactly one call $2e^{-2} \approx 0.271$.|En moyenne 2 appels par minute : la probabilité d’aucun appel dans une minute donnée est $e^{-2} \approx 0{,}135$, d’exactement un appel $2e^{-2} \approx 0{,}271$.|De media 2 llamadas por minuto: la probabilidad de ninguna llamada en un minuto es $e^{-2} \approx 0{,}135$ y de exactamente una, $2e^{-2} \approx 0{,}271$.|平均 1 分に 2 回：0 回の確率 $e^{-2} \approx 0.135$、ちょうど 1 回 $2e^{-2} \approx 0.271$。|平均每分钟 2 个电话：某分钟没有电话的概率 $e^{-2} \approx 0.135$，恰一个 $2e^{-2} \approx 0.271$。`,
      a: [F(R`\lambda = 2:\ P(X = 0) = e^{-2} \approx 0.135`), Y(R`P(X = 1) = 2e^{-2} \approx 0.271`)] },
    { a: [F(R`\lambda = 3`)],
      ex: { k: 'val', v: '4.5e^(-3)', q: R`$X$ is Poisson with $\lambda = 3$. Find $P(X = 2)$.|$X$ suit une loi de Poisson de paramètre $\lambda = 3$. Calculez $P(X = 2)$.|$X$ es de Poisson con $\lambda = 3$. Halla $P(X = 2)$.|$X$ は $\lambda = 3$ のポアソン分布。$P(X = 2)$ を求めよ。|$X$ 服从 $\lambda = 3$ 的泊松分布，求 $P(X = 2)$。`,
        sol: [R`e^{-3}\frac{3^2}{2!}`, R`= 4.5\,e^{-3} \approx 0.224`] } });

  // =============================== Continuous distributions ===============================
  lesson('Continuous distributions/Density', 'Probability density|Densité de probabilité|Función de densidad|確率密度関数|概率密度',
    { s: R`For a continuous variable, single values have probability 0; probabilities are areas under the density curve. So the curve must never go below 0 and the total area must be 1 — that condition usually fixes an unknown constant.|Pour une variable continue, chaque valeur isolée a une probabilité nulle ; les probabilités sont des aires sous la courbe de densité. La courbe ne doit jamais passer sous 0, et l’aire totale doit valoir 1 — cette condition fixe souvent une constante inconnue.|Para una variable continua, cada valor aislado tiene probabilidad 0; las probabilidades son áreas bajo la curva de densidad. La curva nunca puede bajar de 0 y el área total debe ser 1: esa condición suele fijar una constante desconocida.|連続型では 1 点の確率は 0、確率は密度曲線の下の面積。曲線は 0 以上、全面積は 1（未知の定数はこの条件で決まることが多い）。|连续变量取单个值的概率为 0；概率是密度曲线下的面积。曲线不能低于 0，总面积必须为 1——这个条件常用来确定未知常数。`,
      a: [F(R`f \ge 0,\quad \int f = 1`), Y(R`P(a \le X \le b) = \int_a^b f(x)\,dx`), AX([-0.3, 2.4], [-0.1, 1.2]), P('x/2'), SH(0.5, 1.5)] },
    { s: R`$f(x) = kx$ on $[0, 2]$: the area is a triangle $\tfrac12\cdot 2\cdot 2k = 2k = 1$, so $k = \tfrac12$. Then $P(0.5 \le X \le 1.5) = \int_{0.5}^{1.5}\tfrac x2\,dx = \tfrac12$.|$f(x) = kx$ sur $[0, 2]$ : l’aire est un triangle $2k = 1$, donc $k = \tfrac12$. Puis $P(0{,}5 \le X \le 1{,}5) = \int_{0{,}5}^{1{,}5}\tfrac x2\,dx = \tfrac12$.|$f(x) = kx$ en $[0, 2]$: el área es un triángulo $2k = 1$, así que $k = \tfrac12$. Luego $P(0{,}5 \le X \le 1{,}5) = \int_{0{,}5}^{1{,}5}\tfrac x2\,dx = \tfrac12$.|$[0, 2]$ で $f(x) = kx$：面積 $2k = 1$ より $k = \tfrac12$。$P(0.5 \le X \le 1.5) = \tfrac12$。|$f(x) = kx$ 在 $[0, 2]$：面积 $2k = 1$，$k = \tfrac12$；$P(0.5 \le X \le 1.5) = \tfrac12$。`,
      a: [F(R`\int_0^2 kx\,dx = 2k = 1 \Rightarrow k = \tfrac12`), Y(R`P(0.5 \le X \le 1.5) = \left[\tfrac{x^2}{4}\right]_{0.5}^{1.5} = \tfrac12`), AX([-0.3, 2.4], [-0.1, 1.2]), P('x/2'), SH(0.5, 1.5)] },
    { a: [F(R`f(x) = kx^2\ \text{on}\ [0, 3]`), AX([-0.3, 3.4], [-0.1, 1.2]), P('x^2/9')],
      ex: { k: 'val', v: '1/9', q: R`$f(x) = kx^2$ on $[0, 3]$ (0 elsewhere) is a density. Find $k$.|$f(x) = kx^2$ sur $[0, 3]$ (0 ailleurs) est une densité. Trouvez $k$.|$f(x) = kx^2$ en $[0, 3]$ (0 fuera) es una densidad. Halla $k$.|$[0, 3]$ で $f(x) = kx^2$（他は 0）が密度関数となる $k$ を求めよ。|$f(x) = kx^2$（$[0, 3]$ 上，其余为 0）是密度函数，求 $k$。`,
        sol: [R`\int_0^3 kx^2\,dx = 9k`, R`9k = 1 \Rightarrow k = \tfrac19`] } });

  lesson('Continuous distributions/Distribution function', 'Distribution function|Fonction de répartition|Función de distribución|分布関数|分布函数',
    { s: R`$F(x)$ is the probability of being at most $x$: the area under the density up to $x$. It climbs from 0 to 1 and never goes down; its slope is the density. The median is where $F = \tfrac12$.|$F(x)$ est la probabilité d’être au plus $x$ : l’aire sous la densité jusqu’à $x$. Elle monte de 0 à 1 sans jamais redescendre ; sa pente est la densité. La médiane est là où $F = \tfrac12$.|$F(x)$ es la probabilidad de ser como mucho $x$: el área bajo la densidad hasta $x$. Sube de 0 a 1 sin bajar nunca; su pendiente es la densidad. La mediana está donde $F = \tfrac12$.|$F(x)$ は $x$ 以下である確率：$x$ までの密度の下の面積。0 から 1 へ単調に増え、傾きが密度。中央値は $F = \tfrac12$ の点。|$F(x)$ 是不超过 $x$ 的概率：密度曲线下到 $x$ 为止的面积。从 0 增到 1，从不下降；其斜率是密度。中位数是 $F = \tfrac12$ 处。`,
      a: [Y(R`F(x) = P(X \le x) = \int_{-\infty}^x f,\quad F' = f`, { s: 22 }), AX([-0.2, 1.3], [-0.1, 2.2]), P('2x', 'b'), P('x^2', 'y', { d: 400 })] },
    { s: R`$f(x) = 2x$ on $[0, 1]$: $F(x) = x^2$, so $P(X \le 0.5) = 0.25$ and the median solves $x^2 = \tfrac12$: $x = \tfrac{1}{\sqrt2} \approx 0.707$.|$f(x) = 2x$ sur $[0, 1]$ : $F(x) = x^2$, donc $P(X \le 0{,}5) = 0{,}25$ et la médiane vérifie $x^2 = \tfrac12$ : $x \approx 0{,}707$.|$f(x) = 2x$ en $[0, 1]$: $F(x) = x^2$, así que $P(X \le 0{,}5) = 0{,}25$ y la mediana cumple $x^2 = \tfrac12$: $x \approx 0{,}707$.|$f = 2x$：$F = x^2$、$P(X \le 0.5) = 0.25$、中央値 $\tfrac{1}{\sqrt2}$。|$f = 2x$：$F = x^2$，$P(X \le 0.5) = 0.25$，中位数 $\tfrac{1}{\sqrt2}$。`,
      a: [F(R`F(x) = x^2`), Y(R`F(0.5) = 0.25,\quad \text{median } \tfrac{1}{\sqrt2}`)] },
    { a: [F(R`F(x) = 1 - e^{-x}\ (x \ge 0)`), AX([-0.3, 4], [-0.1, 1.2]), P('1-e^(-x)'), P('0.5', 'g', { dash: true })],
      ex: { k: 'val', v: 'ln(2)', q: R`$X$ has distribution function $F(x) = 1 - e^{-x}$ for $x \ge 0$. Find its median.|$X$ a pour fonction de répartition $F(x) = 1 - e^{-x}$ pour $x \ge 0$. Trouvez sa médiane.|$X$ tiene función de distribución $F(x) = 1 - e^{-x}$ para $x \ge 0$. Halla su mediana.|$X$ の分布関数は $F(x) = 1 - e^{-x}$（$x \ge 0$）。中央値を求めよ。|$X$ 的分布函数为 $F(x) = 1 - e^{-x}$（$x \ge 0$），求中位数。`,
        sol: [R`1 - e^{-x} = \tfrac12`, R`e^{-x} = \tfrac12 \Rightarrow x = \ln 2 \approx 0.693`] } });

  lesson('Continuous distributions/Expectation and variance', 'Mean and variance of a density|Espérance et variance d’une densité|Media y varianza de una densidad|連続型の期待値と分散|连续型的期望与方差',
    { s: R`The same formulas as in the discrete case, with sums replaced by integrals: $x$ weighted by the density. The mean is the balance point of the area under $f$.|Mêmes formules que dans le cas discret, les sommes devenant des intégrales : $x$ pondéré par la densité. L’espérance est le point d’équilibre de l’aire sous $f$.|Las mismas fórmulas que en el caso discreto, con integrales en vez de sumas: $x$ ponderado por la densidad. La media es el punto de equilibrio del área bajo $f$.|離散の場合と同じ式で、和を積分に：$x$ を密度で重みづけ。平均は $f$ の下の面積の釣り合いの点。|与离散情形相同，只是把求和换成积分：$x$ 按密度加权。期望是 $f$ 下方面积的平衡点。`,
      a: [Y(R`E[X] = \int x f(x)\,dx`), F(R`\operatorname{Var}X = \int x^2 f(x)\,dx - E[X]^2`), AX([-0.2, 1.3], [-0.1, 2.2]), P('2x'), SH(0, 1), ['pt', 2 / 3, 0, 'E = 2/3', { c: 'o' }]] },
    { s: R`$f(x) = 2x$ on $[0, 1]$: $E = \int_0^1 2x^2\,dx = \tfrac23$, $E[X^2] = \int_0^1 2x^3\,dx = \tfrac12$, so $\operatorname{Var} = \tfrac12 - \tfrac49 = \tfrac1{18}$.|$f(x) = 2x$ sur $[0, 1]$ : $E = \tfrac23$, $E[X^2] = \tfrac12$, donc $\operatorname{Var} = \tfrac1{18}$.|$f(x) = 2x$ en $[0, 1]$: $E = \tfrac23$, $E[X^2] = \tfrac12$, así que $\operatorname{Var} = \tfrac1{18}$.|$f = 2x$：$E = \tfrac23$、$E[X^2] = \tfrac12$、$\operatorname{Var} = \tfrac1{18}$。|$f = 2x$：$E = \tfrac23$，$E[X^2] = \tfrac12$，$\operatorname{Var} = \tfrac1{18}$。`,
      a: [F(R`E = \int_0^1 2x^2\,dx = \tfrac23`), Y(R`\operatorname{Var} = \int_0^1 2x^3\,dx - \tfrac49 = \tfrac1{18}`)] },
    { a: [F(R`f(x) = 3x^2\ \text{on}\ [0, 1]`), AX([-0.2, 1.3], [-0.1, 3.3]), P('3x^2')],
      ex: { k: 'val', v: '3/4', q: R`$X$ has density $f(x) = 3x^2$ on $[0, 1]$. Find $E[X]$.|$X$ a pour densité $f(x) = 3x^2$ sur $[0, 1]$. Calculez $E[X]$.|$X$ tiene densidad $f(x) = 3x^2$ en $[0, 1]$. Halla $E[X]$.|$X$ の密度は $[0, 1]$ で $f(x) = 3x^2$。$E[X]$ を求めよ。|$X$ 在 $[0, 1]$ 上密度为 $f(x) = 3x^2$，求 $E[X]$。`,
        sol: [R`E = \int_0^1 3x^3\,dx`, R`= \tfrac34`] } });

  lesson('Continuous distributions/Uniform on [a, b]', 'Uniform distribution on [a, b]|Loi uniforme sur [a, b]|Distribución uniforme en [a, b]|一様分布 [a, b]|[a, b] 上的均匀分布',
    { s: R`Every point of $[a, b]$ is equally likely: the density is a flat rectangle of height $\tfrac{1}{b - a}$, so probabilities are just lengths over $b - a$. The mean is the midpoint; the variance is $\tfrac{(b - a)^2}{12}$.|Tous les points de $[a, b]$ sont équiprobables : la densité est un rectangle plat de hauteur $\tfrac{1}{b - a}$, et les probabilités sont des longueurs divisées par $b - a$. L’espérance est le milieu ; la variance $\tfrac{(b - a)^2}{12}$.|Todos los puntos de $[a, b]$ son igual de probables: la densidad es un rectángulo plano de altura $\tfrac{1}{b - a}$, así que las probabilidades son longitudes entre $b - a$. La media es el punto medio y la varianza $\tfrac{(b - a)^2}{12}$.|$[a, b]$ のどの点も同じ：密度は高さ $\tfrac{1}{b - a}$ の長方形、確率は長さ ÷ $(b - a)$。平均は中点、分散 $\tfrac{(b - a)^2}{12}$。|$[a, b]$ 上每点等可能：密度是高 $\tfrac{1}{b - a}$ 的矩形，概率就是长度除以 $b - a$。均值是中点，方差 $\tfrac{(b - a)^2}{12}$。`,
      a: [Y(R`f = \frac{1}{b - a},\quad E = \frac{a + b}{2},\quad \operatorname{Var} = \frac{(b - a)^2}{12}`, { s: 22 }), S2([5, 0.1], 4, true), RECT(2, 0, 8, 1 / 6 * 6, 'b', 0.25), RECT(2, 0, 4, 1, 'y', 0.5)] },
    { s: R`Uniform on $[2, 8]$: height $\tfrac16$; $E = 5$; $\operatorname{Var} = \tfrac{36}{12} = 3$; $P(X < 4) = \tfrac{2}{6} = \tfrac13$.|Uniforme sur $[2, 8]$ : hauteur $\tfrac16$ ; $E = 5$ ; $\operatorname{Var} = 3$ ; $P(X < 4) = \tfrac13$.|Uniforme en $[2, 8]$: altura $\tfrac16$; $E = 5$; $\operatorname{Var} = 3$; $P(X < 4) = \tfrac13$.|$[2, 8]$ の一様分布：$E = 5$、$\operatorname{Var} = 3$、$P(X < 4) = \tfrac13$。|$[2, 8]$ 均匀分布：$E = 5$，$\operatorname{Var} = 3$，$P(X < 4) = \tfrac13$。`,
      a: [F(R`E = 5,\quad \operatorname{Var} = \frac{6^2}{12} = 3`), Y(R`P(X < 4) = \frac{4 - 2}{6} = \frac13`)] },
    { a: [F(R`X \sim U[0, 12]`)],
      ex: { k: 'val', v: '12', q: R`$X$ is uniform on $[0, 12]$. Find $\operatorname{Var}X$.|$X$ suit la loi uniforme sur $[0, 12]$. Calculez $\operatorname{Var}X$.|$X$ es uniforme en $[0, 12]$. Halla $\operatorname{Var}X$.|$X$ は $[0, 12]$ の一様分布。$\operatorname{Var}X$ を求めよ。|$X$ 在 $[0, 12]$ 上均匀分布，求 $\operatorname{Var}X$。`,
        sol: [R`\operatorname{Var} = \frac{(12 - 0)^2}{12}`, R`= 12`] } });

  lesson('Continuous distributions/Exponential', 'Exponential distribution|Loi exponentielle|Distribución exponencial|指数分布|指数分布',
    { s: R`Waiting times and lifetimes without wear: the density decays like $e^{-\lambda x}$. The chance of surviving past $t$ is $e^{-\lambda t}$, and the mean lifetime is $\tfrac1\lambda$. It has no memory: having waited does not shorten the remaining wait.|Temps d’attente et durées de vie sans usure : la densité décroît comme $e^{-\lambda x}$. La probabilité de dépasser $t$ est $e^{-\lambda t}$, et la durée moyenne $\tfrac1\lambda$. Sans mémoire : avoir attendu ne raccourcit pas l’attente restante.|Tiempos de espera y vidas sin desgaste: la densidad decae como $e^{-\lambda x}$. La probabilidad de superar $t$ es $e^{-\lambda t}$ y la vida media $\tfrac1\lambda$. No tiene memoria: haber esperado no acorta la espera restante.|待ち時間や摩耗のない寿命：密度は $e^{-\lambda x}$ で減少。$t$ を超えて生き残る確率は $e^{-\lambda t}$、平均寿命 $\tfrac1\lambda$。無記憶性：待ったことで残りが短くはならない。|等待时间和无磨损寿命：密度按 $e^{-\lambda x}$ 衰减。超过 $t$ 的概率为 $e^{-\lambda t}$，平均寿命 $\tfrac1\lambda$。无记忆性：已等待不会缩短剩余等待。`,
      a: [Y(R`f(x) = \lambda e^{-\lambda x},\quad P(X > t) = e^{-\lambda t},\quad E = \frac1\lambda`, { s: 22 }), AX([-0.3, 7], [-0.05, 0.6]), P('0.5e^(-0.5x)'), SH(2, 7)] },
    { s: R`$\lambda = 0.5$ (mean 2): $P(X > 2) = e^{-1} \approx 0.368$ — the shaded tail. Even an average lifetime is exceeded only 37% of the time.|$\lambda = 0{,}5$ (moyenne 2) : $P(X > 2) = e^{-1} \approx 0{,}368$ — la queue hachurée.|$\lambda = 0{,}5$ (media 2): $P(X > 2) = e^{-1} \approx 0{,}368$, la cola sombreada.|$\lambda = 0.5$（平均 2）：$P(X > 2) = e^{-1} \approx 0.368$。|$\lambda = 0.5$（均值 2）：$P(X > 2) = e^{-1} \approx 0.368$。`,
      a: [Y(R`P(X > 2) = e^{-0.5\cdot 2} = e^{-1} \approx 0.368`)] },
    { a: [F(R`E = 4\ \text{years}`)],
      ex: { k: 'val', v: 'e^(-2)', q: R`A component’s lifetime is exponential with mean 4 years. Find the probability that it lasts more than 8 years.|La durée de vie d’un composant suit une loi exponentielle de moyenne 4 ans. Calculez la probabilité qu’il dure plus de 8 ans.|La vida de un componente es exponencial con media 4 años. Halla la probabilidad de que dure más de 8 años.|部品の寿命は平均 4 年の指数分布。8 年より長くもつ確率を求めよ。|某元件寿命服从均值 4 年的指数分布，求寿命超过 8 年的概率。`,
        sol: [R`\lambda = \tfrac14`, R`P(X > 8) = e^{-8/4} = e^{-2} \approx 0.135`] } });

  // =============================== Using the normal distribution ===============================
  lesson('Using the normal distribution/Standardising', 'Standardising|Centrer et réduire|Tipificar|標準化|标准化',
    { s: R`To use the $\Phi$ table, turn each bound into a $z$-score (subtract $\mu$, divide by $\sigma$). A probability between two bounds is the difference of the two table values.|Pour utiliser la table de $\Phi$, on transforme chaque borne en score $z$ (on retranche $\mu$, on divise par $\sigma$). La probabilité entre deux bornes est la différence des deux valeurs lues.|Para usar la tabla de $\Phi$, convierte cada extremo en una puntuación $z$ (resta $\mu$ y divide entre $\sigma$). La probabilidad entre dos extremos es la diferencia de los dos valores de la tabla.|$\Phi$ の表を使うには各境界を $z$ 値に（$\mu$ を引いて $\sigma$ で割る）。2 つの境界の間の確率は表の値の差。|使用 $\Phi$ 表时，把每个界化为 $z$ 值（减 $\mu$ 再除以 $\sigma$）。两界之间的概率是两个表值之差。`,
      a: [Y(R`P(a < X < b) = \Phi\left(\tfrac{b - \mu}{\sigma}\right) - \Phi\left(\tfrac{a - \mu}{\sigma}\right)`, { s: 22 }), AX([-4, 4], [-0.05, 0.5]), P(N01), SH(-1, 2)] },
    { s: R`$X \sim N(50, 5^2)$: $P(45 < X < 60) = \Phi(2) - \Phi(-1) = 0.9772 - 0.1587 = 0.8186$.|$X \sim N(50, 5^2)$ : $P(45 < X < 60) = \Phi(2) - \Phi(-1) = 0{,}9772 - 0{,}1587 = 0{,}8186$.|$X \sim N(50, 5^2)$: $P(45 < X < 60) = \Phi(2) - \Phi(-1) = 0{,}9772 - 0{,}1587 = 0{,}8186$.|$X \sim N(50, 5^2)$：$\Phi(2) - \Phi(-1) = 0.8186$。|$X \sim N(50, 5^2)$：$\Phi(2) - \Phi(-1) = 0.8186$。`,
      a: [F(R`z_1 = \frac{45 - 50}{5} = -1,\quad z_2 = \frac{60 - 50}{5} = 2`), Y(R`\Phi(2) - \Phi(-1) = 0.8186`)] },
    { a: [F(R`X \sim N(20, 4^2),\quad \Phi(1.5) = 0.9332`), AX([-4, 4], [-0.05, 0.5]), P(N01), SH(-4, 1.5)],
      ex: { k: 'val', v: '0.9332', q: R`$X \sim N(20, 4^2)$. Find $P(X < 26)$ (use $\Phi(1.5) = 0.9332$).|$X \sim N(20, 4^2)$. Calculez $P(X < 26)$ (on donne $\Phi(1{,}5) = 0{,}9332$).|$X \sim N(20, 4^2)$. Halla $P(X < 26)$ (usa $\Phi(1{,}5) = 0{,}9332$).|$X \sim N(20, 4^2)$。$P(X < 26)$ を求めよ（$\Phi(1.5) = 0.9332$）。|$X \sim N(20, 4^2)$，求 $P(X < 26)$（$\Phi(1.5) = 0.9332$）。`,
        sol: [R`z = \frac{26 - 20}{4} = 1.5`, R`P = \Phi(1.5) = 0.9332`] } });

  lesson('Using the normal distribution/Symmetry', 'Symmetry of the normal curve|Symétrie de la courbe de Gauss|Simetría de la normal|正規分布の対称性|正态曲线的对称性',
    { s: R`Tables only give $\Phi$ for positive $z$. The bell is symmetric, so the left tail at $-z$ equals the right tail at $z$: $\Phi(-z) = 1 - \Phi(z)$. For a central interval, remove both tails: $2\Phi(z) - 1$.|Les tables ne donnent $\Phi$ que pour $z$ positif. La cloche est symétrique : la queue gauche en $-z$ égale la queue droite en $z$, $\Phi(-z) = 1 - \Phi(z)$. Pour un intervalle centré, on retire les deux queues : $2\Phi(z) - 1$.|Las tablas solo dan $\Phi$ para $z$ positivo. La campana es simétrica, así que la cola izquierda en $-z$ es igual a la derecha en $z$: $\Phi(-z) = 1 - \Phi(z)$. Para un intervalo centrado, quita las dos colas: $2\Phi(z) - 1$.|表は正の $z$ だけ。対称なので $-z$ の左裾は $z$ の右裾と同じ：$\Phi(-z) = 1 - \Phi(z)$。中央の区間は両裾を除いて $2\Phi(z) - 1$。|表只给正 $z$ 的 $\Phi$。钟形对称，$-z$ 的左尾等于 $z$ 的右尾：$\Phi(-z) = 1 - \Phi(z)$。中心区间去掉两尾：$2\Phi(z) - 1$。`,
      a: [Y(R`\Phi(-z) = 1 - \Phi(z)`), F(R`P(\lvert Z\rvert \le z) = 2\Phi(z) - 1`), AX([-4, 4], [-0.05, 0.5]), P(N01), SH(-4, -1.2)] },
    { s: R`$\Phi(-1.2) = 1 - \Phi(1.2) = 1 - 0.8849 = 0.1151$: the small left tail in the picture.|$\Phi(-1{,}2) = 1 - 0{,}8849 = 0{,}1151$ : la petite queue gauche de la figure.|$\Phi(-1{,}2) = 1 - 0{,}8849 = 0{,}1151$: la pequeña cola izquierda de la figura.|$\Phi(-1.2) = 1 - 0.8849 = 0.1151$。|$\Phi(-1.2) = 1 - 0.8849 = 0.1151$。`,
      a: [Y(R`\Phi(-1.2) = 1 - 0.8849 = 0.1151`)] },
    { a: [F(R`\Phi(1.5) = 0.9332`), AX([-4, 4], [-0.05, 0.5]), P(N01), SH(-1.5, 1.5)],
      ex: { k: 'val', v: '0.8664', q: R`Using $\Phi(1.5) = 0.9332$, find $P(\lvert Z\rvert \le 1.5)$.|Avec $\Phi(1{,}5) = 0{,}9332$, calculez $P(\lvert Z\rvert \le 1{,}5)$.|Con $\Phi(1{,}5) = 0{,}9332$, halla $P(\lvert Z\rvert \le 1{,}5)$.|$\Phi(1.5) = 0.9332$ を用いて $P(\lvert Z\rvert \le 1.5)$ を求めよ。|已知 $\Phi(1.5) = 0.9332$，求 $P(\lvert Z\rvert \le 1.5)$。`,
        sol: [R`2\Phi(1.5) - 1`, R`= 2\cdot 0.9332 - 1 = 0.8664`] } });

  lesson('Using the normal distribution/Key values', 'Key values of Φ|Valeurs clés de Φ|Valores clave de Φ|Φ の重要な値|Φ 的关键值',
    { s: R`Three numbers worth memorising: $1.645$ leaves 5% in one tail, $1.96$ leaves 2.5% in each tail (95% in the middle), $2.576$ leaves 0.5% in each tail (99% in the middle). They appear in every confidence interval and test.|Trois nombres à retenir : $1{,}645$ laisse 5 % dans une queue, $1{,}96$ laisse 2,5 % dans chaque queue (95 % au centre), $2{,}576$ laisse 0,5 % dans chaque queue (99 % au centre). On les retrouve dans tout intervalle de confiance et tout test.|Tres números que conviene recordar: $1{,}645$ deja un 5 % en una cola, $1{,}96$ deja un 2,5 % en cada cola (95 % en el centro) y $2{,}576$ un 0,5 % en cada cola (99 % en el centro). Aparecen en todo intervalo de confianza y contraste.|覚えておく 3 つの数：$1.645$ は片側 5%、$1.96$ は両側 2.5% ずつ（中央 95%）、$2.576$ は両側 0.5% ずつ（中央 99%）。信頼区間や検定で必ず登場。|值得记住的三个数：$1.645$ 单侧留 5%，$1.96$ 两侧各留 2.5%（中间 95%），$2.576$ 两侧各留 0.5%（中间 99%）。所有置信区间和检验中都会出现。`,
      a: [F(R`\Phi(1.645) \approx 0.95,\ \Phi(1.96) \approx 0.975,\ \Phi(2.576) \approx 0.995`, { s: 20 }), AX([-4, 4], [-0.05, 0.5]), P(N01), SH(-1.96, 1.96)] },
    { s: R`95% of a normal population lies within $\mu \pm 1.96\sigma$. With $\mu = 100$, $\sigma = 15$: from $70.6$ to $129.4$.|95 % d’une population normale est dans $\mu \pm 1{,}96\sigma$. Avec $\mu = 100$, $\sigma = 15$ : de $70{,}6$ à $129{,}4$.|El 95 % de una población normal está en $\mu \pm 1{,}96\sigma$. Con $\mu = 100$, $\sigma = 15$: de $70{,}6$ a $129{,}4$.|正規母集団の 95% は $\mu \pm 1.96\sigma$：$\mu = 100$, $\sigma = 15$ なら 70.6〜129.4。|正态总体 95% 落在 $\mu \pm 1.96\sigma$：$\mu = 100$，$\sigma = 15$ 时为 70.6 到 129.4。`,
      a: [Y(R`100 \pm 1.96\cdot 15 = [70.6,\ 129.4]`)] },
    { a: [F(R`P(Z > 1.645)`), AX([-4, 4], [-0.05, 0.5]), P(N01), SH(1.645, 4)],
      ex: { k: 'val', v: '0.05', q: R`Find $P(Z > 1.645)$.|Calculez $P(Z > 1{,}645)$.|Calcula $P(Z > 1{,}645)$.|$P(Z > 1.645)$ を求めよ。|求 $P(Z > 1.645)$。`, sol: [R`1 - \Phi(1.645)`, R`\approx 1 - 0.95 = 0.05`] } });

  lesson('Using the normal distribution/Normal approximation to the binomial', 'Normal approximation to the binomial|Approximation normale de la binomiale|Aproximación normal a la binomial|二項分布の正規近似|二项分布的正态近似',
    { s: R`For large $n$ the binomial bars look like a bell with the same mean $np$ and variance $np(1 - p)$. Each bar covers an interval of width 1, so add $0.5$ to the bound (continuity correction) before standardising.|Pour $n$ grand, les barres de la binomiale ressemblent à une cloche de même moyenne $np$ et même variance $np(1 - p)$. Chaque barre couvre un intervalle de largeur 1 : on ajoute $0{,}5$ à la borne (correction de continuité) avant de centrer-réduire.|Para $n$ grande las barras de la binomial parecen una campana con la misma media $np$ y varianza $np(1 - p)$. Cada barra cubre un intervalo de anchura 1, así que suma $0{,}5$ al extremo (corrección por continuidad) antes de tipificar.|$n$ が大きいと二項分布の棒は平均 $np$・分散 $np(1 - p)$ のベル曲線に似る。各棒は幅 1 なので、標準化の前に境界に 0.5 を足す（連続補正）。|$n$ 较大时二项分布的条形像均值 $np$、方差 $np(1 - p)$ 的钟形。每个条形宽 1，标准化前给边界加 0.5（连续性修正）。`,
      a: [Y(R`B(n, p) \approx N\big(np,\ np(1 - p)\big)`), F(R`P(X \le k) \approx \Phi\left(\frac{k + 0.5 - np}{\sqrt{np(1 - p)}}\right)`, { s: 22 }), S2([10, 1.6], 7, true), ...BARS(binom(20, 0.5), 0, 18)] },
    { s: R`$n = 100$ coins: $\mu = 50$, $\sigma = 5$. $P(X \le 55) \approx \Phi\left(\tfrac{55.5 - 50}{5}\right) = \Phi(1.1) \approx 0.864$.|$n = 100$ pièces : $\mu = 50$, $\sigma = 5$. $P(X \le 55) \approx \Phi(1{,}1) \approx 0{,}864$.|$n = 100$ monedas: $\mu = 50$, $\sigma = 5$. $P(X \le 55) \approx \Phi(1{,}1) \approx 0{,}864$.|硬貨 100 枚：$\mu = 50$, $\sigma = 5$。$P(X \le 55) \approx \Phi(1.1) \approx 0.864$。|100 枚硬币：$\mu = 50$，$\sigma = 5$。$P(X \le 55) \approx \Phi(1.1) \approx 0.864$。`,
      a: [F(R`\mu = 50,\quad \sigma = \sqrt{100\cdot 0.25} = 5`), Y(R`P(X \le 55) \approx \Phi(1.1) \approx 0.864`)] },
    { a: [F(R`X \sim B(400, 0.2)`)],
      ex: { k: 'val', v: '8', q: R`$X \sim B(400, 0.2)$ is approximated by a normal. What is the standard deviation of that normal?|$X \sim B(400 ; 0{,}2)$ est approchée par une loi normale. Quel est son écart-type ?|$X \sim B(400, 0{,}2)$ se aproxima por una normal. ¿Cuál es su desviación típica?|$X \sim B(400, 0.2)$ を正規分布で近似する。その標準偏差を求めよ。|$X \sim B(400, 0.2)$ 用正态近似，其标准差是多少？`,
        sol: [R`np(1 - p) = 400\cdot 0.2\cdot 0.8 = 64`, R`\sigma = 8`] } });

  lesson('Using the normal distribution/Mean of a sample', 'The mean of a sample|Moyenne d’un échantillon|Media muestral|標本平均|样本均值',
    { s: R`Averaging $n$ observations keeps the mean $\mu$ but shrinks the spread by $\sqrt n$: $\sigma/\sqrt n$, the standard error. That is why a 95% confidence interval for $\mu$ is $\bar x \pm 1.96\tfrac{\sigma}{\sqrt n}$ — four times the sample size halves its width.|Faire la moyenne de $n$ observations garde la moyenne $\mu$ mais réduit la dispersion d’un facteur $\sqrt n$ : $\sigma/\sqrt n$. D’où l’intervalle de confiance à 95 % pour $\mu$ : $\bar x \pm 1{,}96\tfrac{\sigma}{\sqrt n}$ — quadrupler l’échantillon divise sa largeur par deux.|Promediar $n$ observaciones mantiene la media $\mu$ pero reduce la dispersión en $\sqrt n$: $\sigma/\sqrt n$, el error típico. Por eso el intervalo de confianza al 95 % para $\mu$ es $\bar x \pm 1{,}96\tfrac{\sigma}{\sqrt n}$: cuadruplicar la muestra reduce su anchura a la mitad.|$n$ 個の平均は平均 $\mu$ のまま、ばらつきは $\sqrt n$ 分の 1（標準誤差 $\sigma/\sqrt n$）。$\mu$ の 95% 信頼区間は $\bar x \pm 1.96\tfrac{\sigma}{\sqrt n}$。標本を 4 倍にすると幅は半分。|对 $n$ 个观测求平均，均值仍为 $\mu$，离散缩小为 $\sigma/\sqrt n$（标准误）。所以 $\mu$ 的 95% 置信区间是 $\bar x \pm 1.96\tfrac{\sigma}{\sqrt n}$——样本量变 4 倍，宽度减半。`,
      a: [Y(R`\bar X \sim N\left(\mu,\ \frac{\sigma^2}{n}\right)`), F(R`\bar x \pm z_{\alpha/2}\frac{\sigma}{\sqrt n}`), AX([-4, 4], [-0.05, 1.3]), P(N01, 'b'), P('3e^(-9x^2/2)/sqrt(2pi)', 'y', { d: 400 })] },
    { s: R`$\sigma = 12$, $n = 36$: the standard error is $2$, so a 95% interval is $\bar x \pm 1.96\cdot 2 = \bar x \pm 3.92$.|$\sigma = 12$, $n = 36$ : l’erreur type vaut $2$, l’intervalle à 95 % est $\bar x \pm 3{,}92$.|$\sigma = 12$, $n = 36$: el error típico es $2$, así que el intervalo al 95 % es $\bar x \pm 3{,}92$.|$\sigma = 12$, $n = 36$：標準誤差 2、95% 区間 $\bar x \pm 3.92$。|$\sigma = 12$，$n = 36$：标准误 2，95% 区间 $\bar x \pm 3.92$。`,
      a: [F(R`\frac{\sigma}{\sqrt n} = \frac{12}{6} = 2`), Y(R`\bar x \pm 1.96\cdot 2 = \bar x \pm 3.92`)] },
    { a: [F(R`\sigma = 10,\ n = 25,\ \bar x = 52`)],
      ex: { k: 'val', v: '55.92', q: R`$\sigma = 10$, $n = 25$, $\bar x = 52$. Find the upper end of the 95% confidence interval for $\mu$.|$\sigma = 10$, $n = 25$, $\bar x = 52$. Donnez la borne supérieure de l’intervalle de confiance à 95 % pour $\mu$.|$\sigma = 10$, $n = 25$, $\bar x = 52$. Halla el extremo superior del intervalo de confianza al 95 % para $\mu$.|$\sigma = 10$, $n = 25$, $\bar x = 52$。$\mu$ の 95% 信頼区間の上端を求めよ。|$\sigma = 10$，$n = 25$，$\bar x = 52$，求 $\mu$ 的 95% 置信区间上限。`,
        sol: [R`\frac{\sigma}{\sqrt n} = 2`, R`52 + 1.96\cdot 2 = 55.92`] } });

  // =============================== Contingency tables ===============================
  const TABLE = (rows, hl = []) => [S2([1.5, 0], 2.6), ...SEQ(rows.flatMap((r, i) => r.map((v, j) => ['lab3', Z(j * 1.25 - 0.4, 1.4 - i * 0.9), String(v), { c: hl.some(([a, b]) => a === i && b === j) ? 'y' : i === 0 || j === 0 ? 'b' : 'chalk', size: 18 }])), 200, 35),
    SG([-0.7, 1.0], [4.4, 1.0], 'chalk', { d: 150 }), SG([0.45, 1.8], [0.45, -1.6], 'chalk', { d: 150 })];
  const T1 = [['', 'B', 'B̄', 'Σ'], ['A', '0.3', '0.2', '0.5'], ['Ā', '0.15', '0.35', '0.5'], ['Σ', '0.45', '0.55', '1']];
  lesson('Contingency tables/A', 'Contingency table: row A|Tableau croisé : ligne A|Tabla de contingencia: fila A|分割表：A の行|列联表：A 行',
    { s: R`Each inside cell is the probability of a combination, such as $A$ and $B$. A row adds up: $P(A \cap B) + P(A \cap \bar B) = P(A)$, because $B$ and $\bar B$ split $A$ into two parts.|Chaque case intérieure est la probabilité d’une combinaison, comme $A$ et $B$. Une ligne s’additionne : $P(A \cap B) + P(A \cap \bar B) = P(A)$, car $B$ et $\bar B$ partagent $A$ en deux.|Cada celda interior es la probabilidad de una combinación, como $A$ y $B$. Una fila se suma: $P(A \cap B) + P(A \cap \bar B) = P(A)$, porque $B$ y $\bar B$ dividen $A$ en dos partes.|内側のマスは組合せ（$A$ かつ $B$ など）の確率。行の和：$P(A \cap B) + P(A \cap \bar B) = P(A)$（$B$ と $\bar B$ が $A$ を 2 つに分ける）。|内部每格是一种组合的概率，如 $A$ 且 $B$。一行相加：$P(A \cap B) + P(A \cap \bar B) = P(A)$，因为 $B$ 与 $\bar B$ 把 $A$ 分成两部分。`,
      a: [Y(R`P(A \cap B) + P(A \cap \bar B) = P(A)`), ...TABLE(T1, [[1, 1], [1, 2], [1, 3]])] },
    { s: R`In the table, $0.3 + 0.2 = 0.5 = P(A)$. Filling a table usually means using these sums in rows and columns until every cell is known.|Dans le tableau, $0{,}3 + 0{,}2 = 0{,}5 = P(A)$. Remplir un tableau, c’est utiliser ces sommes en ligne et en colonne jusqu’à tout connaître.|En la tabla, $0{,}3 + 0{,}2 = 0{,}5 = P(A)$. Rellenar una tabla consiste en usar estas sumas por filas y columnas hasta conocerlo todo.|表で $0.3 + 0.2 = 0.5 = P(A)$。表を埋めるには行と列の和を使う。|表中 $0.3 + 0.2 = 0.5 = P(A)$。填表就是反复利用行列之和。`,
      a: [Y(R`0.3 + 0.2 = 0.5`), ...TABLE(T1, [[1, 3]])] },
    { a: [F(R`P(A \cap B) = 0.3,\quad P(A \cap \bar B) = 0.2`)],
      ex: { k: 'val', v: '0.5', q: R`$P(A \cap B) = 0.3$ and $P(A \cap \bar B) = 0.2$. Find $P(A)$.|$P(A \cap B) = 0{,}3$ et $P(A \cap \bar B) = 0{,}2$. Calculez $P(A)$.|$P(A \cap B) = 0{,}3$ y $P(A \cap \bar B) = 0{,}2$. Halla $P(A)$.|$P(A \cap B) = 0.3$, $P(A \cap \bar B) = 0.2$。$P(A)$ を求めよ。|$P(A \cap B) = 0.3$，$P(A \cap \bar B) = 0.2$，求 $P(A)$。`, sol: [R`P(A) = 0.3 + 0.2 = 0.5`] } });

  lesson(R`Contingency tables/\bar A`, 'Contingency table: row Ā|Tableau croisé : ligne Ā|Tabla de contingencia: fila Ā|分割表：Ā の行|列联表：Ā 行',
    { s: R`The row of $\bar A$ works the same way, and its total is $1 - P(A)$. Columns add up too: $P(A \cap B) + P(\bar A \cap B) = P(B)$ — that is how you find a missing cell.|La ligne de $\bar A$ fonctionne pareil, et son total vaut $1 - P(A)$. Les colonnes s’additionnent aussi : $P(A \cap B) + P(\bar A \cap B) = P(B)$ — c’est ainsi qu’on trouve une case manquante.|La fila de $\bar A$ funciona igual y su total es $1 - P(A)$. Las columnas también suman: $P(A \cap B) + P(\bar A \cap B) = P(B)$; así se halla una celda que falta.|$\bar A$ の行も同じで、合計は $1 - P(A)$。列も足せる：$P(A \cap B) + P(\bar A \cap B) = P(B)$（欠けたマスを求める方法）。|$\bar A$ 行同理，合计为 $1 - P(A)$。列也可相加：$P(A \cap B) + P(\bar A \cap B) = P(B)$——缺格就这样求。`,
      a: [Y(R`P(\bar A \cap B) + P(\bar A \cap \bar B) = P(\bar A) = 1 - P(A)`, { s: 22 }), ...TABLE(T1, [[2, 1], [2, 2], [2, 3]])] },
    { s: R`$P(\bar A) = 1 - 0.5 = 0.5$, and in column $B$: $P(\bar A \cap B) = P(B) - P(A \cap B) = 0.45 - 0.3 = 0.15$.|$P(\bar A) = 0{,}5$ et, dans la colonne $B$ : $P(\bar A \cap B) = 0{,}45 - 0{,}3 = 0{,}15$.|$P(\bar A) = 0{,}5$ y, en la columna $B$: $P(\bar A \cap B) = 0{,}45 - 0{,}3 = 0{,}15$.|$P(\bar A) = 0.5$、列 $B$ で $P(\bar A \cap B) = 0.45 - 0.3 = 0.15$。|$P(\bar A) = 0.5$；$B$ 列：$P(\bar A \cap B) = 0.45 - 0.3 = 0.15$。`,
      a: [Y(R`P(\bar A \cap B) = 0.45 - 0.3 = 0.15`), ...TABLE(T1, [[2, 1]])] },
    { a: [F(R`P(B) = 0.45,\quad P(A \cap B) = 0.3`)],
      ex: { k: 'val', v: '0.15', q: R`$P(B) = 0.45$ and $P(A \cap B) = 0.3$. Find $P(\bar A \cap B)$.|$P(B) = 0{,}45$ et $P(A \cap B) = 0{,}3$. Calculez $P(\bar A \cap B)$.|$P(B) = 0{,}45$ y $P(A \cap B) = 0{,}3$. Halla $P(\bar A \cap B)$.|$P(B) = 0.45$, $P(A \cap B) = 0.3$。$P(\bar A \cap B)$ を求めよ。|$P(B) = 0.45$，$P(A \cap B) = 0.3$，求 $P(\bar A \cap B)$。`, sol: [R`P(\bar A \cap B) = P(B) - P(A \cap B)`, R`= 0.15`] } });

  lesson('Contingency tables/~Total|Total|Total|計|合计', 'Contingency table: the totals|Tableau croisé : les totaux|Tabla de contingencia: los totales|分割表：合計の行|列联表：合计行',
    { s: R`The bottom row holds the column totals $P(B)$ and $P(\bar B)$, the right column holds $P(A)$ and $P(\bar A)$, and the corner is 1: everything together. Always check that both directions add up to 1.|La dernière ligne contient les totaux de colonne $P(B)$ et $P(\bar B)$, la dernière colonne $P(A)$ et $P(\bar A)$, et le coin vaut 1 : tout réuni. Vérifiez toujours que les deux sens donnent 1.|La última fila tiene los totales de columna $P(B)$ y $P(\bar B)$, la última columna $P(A)$ y $P(\bar A)$, y la esquina es 1: todo junto. Comprueba siempre que ambos sentidos suman 1.|最下行は列の合計 $P(B)$, $P(\bar B)$、右の列は $P(A)$, $P(\bar A)$、角は 1。縦横どちらの合計も 1 になるか確認。|最后一行是列合计 $P(B)$、$P(\bar B)$，最后一列是 $P(A)$、$P(\bar A)$，角上为 1：全部合在一起。始终检查两个方向都加到 1。`,
      a: [Y(R`P(B) + P(\bar B) = 1`), ...TABLE(T1, [[3, 1], [3, 2], [3, 3]])] },
    { s: R`In the table $0.45 + 0.55 = 1$ and $0.5 + 0.5 = 1$. If they do not, some cell is wrong.|Dans le tableau $0{,}45 + 0{,}55 = 1$ et $0{,}5 + 0{,}5 = 1$. Sinon, une case est fausse.|En la tabla $0{,}45 + 0{,}55 = 1$ y $0{,}5 + 0{,}5 = 1$. Si no, alguna celda está mal.|表で $0.45 + 0.55 = 1$、$0.5 + 0.5 = 1$。合わなければどこかが誤り。|表中 $0.45 + 0.55 = 1$，$0.5 + 0.5 = 1$。否则某格有误。`,
      a: [Y(R`0.45 + 0.55 = 1,\quad 0.5 + 0.5 = 1`), ...TABLE(T1, [[3, 3]])] },
    { a: [F(R`P(B) = 0.45`)],
      ex: { k: 'val', v: '0.55', q: R`$P(B) = 0.45$. Fill in the total $P(\bar B)$.|$P(B) = 0{,}45$. Complétez le total $P(\bar B)$.|$P(B) = 0{,}45$. Completa el total $P(\bar B)$.|$P(B) = 0.45$。合計 $P(\bar B)$ を求めよ。|$P(B) = 0.45$，填出合计 $P(\bar B)$。`, sol: [R`P(\bar B) = 1 - 0.45 = 0.55`] } });

  lesson('Contingency tables/Reading conditional probabilities', 'Reading conditional probabilities|Lire des probabilités conditionnelles|Leer probabilidades condicionadas|表から条件付き確率を読む|从表中读条件概率',
    { s: R`“Given $B$” restricts you to the $B$ column: divide the cell by the column total. “Given $A$” restricts you to the $A$ row: divide by the row total. The most common mistake is dividing by the wrong total.|« Sachant $B$ » limite à la colonne $B$ : on divise la case par le total de la colonne. « Sachant $A$ » limite à la ligne $A$ : on divise par le total de la ligne. L’erreur la plus fréquente est de diviser par le mauvais total.|«Sabiendo $B$» te limita a la columna $B$: divide la celda entre el total de la columna. «Sabiendo $A$» te limita a la fila $A$: divide entre el total de la fila. El error más común es dividir por el total equivocado.|「$B$ のもとで」は $B$ の列に限る：マス ÷ 列の合計。「$A$ のもとで」は $A$ の行：行の合計で割る。最も多いミスは割る合計を間違えること。|“已知 $B$”限于 $B$ 列：格除以列合计。“已知 $A$”限于 $A$ 行：除以行合计。最常见的错误是除错了合计。`,
      a: [Y(R`P(A \mid B) = \frac{P(A \cap B)}{P(B)}`), ...TABLE(T1, [[1, 1], [3, 1]])] },
    { s: R`$P(A \mid B) = \tfrac{0.3}{0.45} = \tfrac23$: two thirds of the $B$ column is in row $A$.|$P(A \mid B) = \tfrac{0{,}3}{0{,}45} = \tfrac23$ : les deux tiers de la colonne $B$ sont dans la ligne $A$.|$P(A \mid B) = \tfrac{0{,}3}{0{,}45} = \tfrac23$: dos tercios de la columna $B$ están en la fila $A$.|$P(A \mid B) = \tfrac{0.3}{0.45} = \tfrac23$。|$P(A \mid B) = \tfrac{0.3}{0.45} = \tfrac23$。`,
      a: [Y(R`P(A \mid B) = \frac{0.3}{0.45} = \frac23`), ...TABLE(T1, [[1, 1], [3, 1]])] },
    { a: [...TABLE(T1)],
      ex: { k: 'val', v: '0.6', q: R`Using the table, find $P(B \mid A)$.|À l’aide du tableau, calculez $P(B \mid A)$.|Con la tabla, halla $P(B \mid A)$.|表を使って $P(B \mid A)$ を求めよ。|根据表格求 $P(B \mid A)$。`, sol: [R`P(B \mid A) = \frac{P(A \cap B)}{P(A)} = \frac{0.3}{0.5}`, R`= 0.6`] } });

  lesson('Contingency tables/Tree diagrams', 'Tree diagrams|Arbres pondérés|Diagramas de árbol|樹形図|树形图',
    { s: R`Each branch carries a probability; the branches leaving a node add up to 1. Multiply along a path to get the probability of that whole path; add the paths that end in the same event (total probability).|Chaque branche porte une probabilité ; les branches issues d’un nœud font 1. On multiplie le long d’un chemin pour obtenir sa probabilité ; on additionne les chemins qui mènent au même événement (probabilités totales).|Cada rama lleva una probabilidad; las ramas que salen de un nodo suman 1. Multiplica a lo largo de un camino para obtener su probabilidad; suma los caminos que acaban en el mismo suceso (probabilidad total).|各枝に確率、1 つの節点から出る枝の和は 1。道に沿って掛けるとその道の確率、同じ事象に至る道を足す（全確率）。|每条分支标有概率；从一个节点出发的分支和为 1。沿路径相乘得到该路径概率；把通向同一事件的路径相加（全概率）。`,
      a: [F(R`P(A \cap B) = P(A)\,P(B \mid A)`), Y(R`P(B) = P(A)P(B \mid A) + P(\bar A)P(B \mid \bar A)`, { s: 22 }), ...TREE('0.3', '0.4', '0.1', ['R', 'R̄'], ['L', 'L̄'])] },
    { s: R`Rain with probability 0.3; late with 0.4 if it rains, 0.1 if not. $P(\text{late}) = 0.3\cdot 0.4 + 0.7\cdot 0.1 = 0.12 + 0.07 = 0.19$.|Pluie avec probabilité 0,3 ; retard 0,4 s’il pleut, 0,1 sinon. $P(\text{retard}) = 0{,}12 + 0{,}07 = 0{,}19$.|Lluvia con probabilidad 0,3; retraso 0,4 si llueve y 0,1 si no. $P(\text{retraso}) = 0{,}12 + 0{,}07 = 0{,}19$.|雨の確率 0.3、雨なら遅刻 0.4、晴れなら 0.1：$P(\text{遅刻}) = 0.19$。|下雨概率 0.3；下雨迟到概率 0.4，否则 0.1：$P(\text{迟到}) = 0.19$。`,
      a: [F(R`0.3\cdot 0.4 + 0.7\cdot 0.1`), Y(R`= 0.19`), ...TREE('0.3', '0.4', '0.1', ['R', 'R̄'], ['L', 'L̄'])] },
    { a: [F(R`3R,\ 2W,\ \text{no replacement}`), ...TREE('3/5', '2/4', '3/4', ['R', 'W'], ['R', 'W'])],
      ex: { k: 'val', v: '3/5', q: R`An urn has 3 red and 2 white balls. Two are drawn without replacement. Find $P(\text{second is red})$.|Une urne contient 3 boules rouges et 2 blanches. On en tire deux sans remise. Calculez $P(\text{la deuxième est rouge})$.|Una urna tiene 3 bolas rojas y 2 blancas. Se sacan dos sin reemplazo. Halla $P(\text{la segunda es roja})$.|赤 3・白 2 の袋から非復元で 2 個取る。2 個目が赤である確率を求めよ。|袋中 3 红 2 白，不放回取两个，求第二个是红球的概率。`,
        sol: [R`\tfrac35\cdot\tfrac24 + \tfrac25\cdot\tfrac34`, R`= \tfrac{6}{20} + \tfrac{6}{20} = \tfrac35`] } });

  // =============================== Classic facts ===============================
  lesson('Classic facts/Two dice', 'Two dice|Deux dés|Dos dados|さいころ 2 個|两颗骰子',
    { s: R`Of the 36 equally likely pairs, the sum 7 appears 6 times — along a diagonal of the grid — more than any other sum. The number of ways falls by one for each step away from 7.|Parmi les 36 couples équiprobables, la somme 7 apparaît 6 fois — sur une diagonale de la grille — plus que toute autre. Le nombre de façons diminue de un à chaque pas qui s’éloigne de 7.|De los 36 pares igual de probables, la suma 7 aparece 6 veces (una diagonal de la cuadrícula), más que cualquier otra. El número de formas baja en uno por cada paso que te alejas de 7.|36 通りのうち和 7 は 6 回（格子の対角線）で最多。7 から 1 離れるごとに 1 通りずつ減る。|36 种等可能的组合中，和为 7 出现 6 次（网格的一条对角线），比其他和都多。每偏离 7 一步就少一种。`,
      a: [Y(R`P(\Sigma = 7) = \frac{6}{36} = \frac16`), F(R`\#(\Sigma = s) = 6 - \lvert s - 7\rvert`), S2([3.5, 3.5], 3.3), ...SEQ([...Array(36)].map((_, k) => { const a = k % 6 + 1, b = Math.floor(k / 6) + 1; return PT([a, b], '', a + b === 7 ? 'y' : 'chalk'); }), 200, 25)] },
    { s: R`Sum 9: $6 - \lvert 9 - 7\rvert = 4$ ways — $(3,6), (4,5), (5,4), (6,3)$ — so $P = \tfrac{4}{36} = \tfrac19$.|Somme 9 : $6 - 2 = 4$ façons, donc $P = \tfrac19$.|Suma 9: $6 - 2 = 4$ formas, así que $P = \tfrac19$.|和 9：4 通りで $P = \tfrac19$。|和为 9：4 种，$P = \tfrac19$。`,
      a: [F(R`6 - \lvert 9 - 7\rvert = 4`), Y(R`P(\Sigma = 9) = \frac{4}{36} = \frac19`)] },
    { a: [F(R`\Sigma = 10`)],
      ex: { k: 'val', v: '1/12', q: R`Two dice are rolled. Find $P(\text{sum} = 10)$.|On lance deux dés. Calculez $P(\text{somme} = 10)$.|Se lanzan dos dados. Halla $P(\text{suma} = 10)$.|さいころ 2 個で $P(\text{和} = 10)$ を求めよ。|掷两颗骰子，求 $P(\text{和} = 10)$。`, sol: [R`6 - \lvert 10 - 7\rvert = 3\ \text{ways}`, R`\frac{3}{36} = \frac1{12}`] } });

  lesson('Classic facts/Birthday problem', 'The birthday problem|Le paradoxe des anniversaires|El problema del cumpleaños|誕生日問題|生日问题',
    { s: R`Count the complement: everyone has a different birthday. The first person can have any day, the second must avoid one day, the third two days… With 23 people the chance of a shared birthday already passes 50% — because there are 253 pairs.|On compte le contraire : tous ont des anniversaires différents. Le premier a n’importe quel jour, le deuxième doit en éviter un, le troisième deux… Avec 23 personnes, la probabilité d’un anniversaire commun dépasse déjà 50 % — car il y a 253 paires.|Cuenta el contrario: todos cumplen años en días distintos. El primero puede tener cualquier día, el segundo debe evitar uno, el tercero dos… Con 23 personas la probabilidad de coincidir ya supera el 50 %, porque hay 253 parejas.|余事象を数える：全員の誕生日が異なる。1 人目は何日でもよく、2 人目は 1 日、3 人目は 2 日を避ける…。23 人でもう 50% を超える（ペアが 253 組あるため）。|算对立事件：所有人生日都不同。第一个人任意，第二个避开一天，第三个避开两天……23 人时有人同生日的概率已超过 50%——因为有 253 对。`,
      a: [Y(R`1 - \frac{365\cdot 364\cdots(365 - n + 1)}{365^n}`), ['ax', { xw: [0, 60], yw: [-0.05, 1.1] }], ['p', 'y=1-e^(-x(x-1)/730)', { c: 'y' }], ['pt', 23, 0.5, 'n = 23', { c: 'o' }]] },
    { s: R`With $n = 23$: $1 - \tfrac{365\cdot 364\cdots 343}{365^{23}} \approx 0.507$. With 50 people it is already about 97%.|Avec $n = 23$ : $\approx 0{,}507$. Avec 50 personnes, environ 97 %.|Con $n = 23$: $\approx 0{,}507$. Con 50 personas, ya un 97 %.|$n = 23$ で約 0.507、50 人で約 97%。|$n = 23$ 时约 0.507；50 人时约 97%。`,
      a: [Y(R`n = 23:\ \approx 0.507`), F(R`n = 50:\ \approx 0.97`)] },
    { a: [F(R`n = 3`)],
      ex: { k: 'val', v: '1-364*363/365^2', q: R`Find the probability that among 3 people at least two share a birthday (365 days).|Calculez la probabilité que parmi 3 personnes au moins deux aient le même anniversaire (365 jours).|Halla la probabilidad de que entre 3 personas al menos dos cumplan el mismo día (365 días).|3 人のうち少なくとも 2 人の誕生日が同じ確率を求めよ（365 日）。|求 3 人中至少两人同一天生日的概率（365 天）。`,
        sol: [R`P(\text{all different}) = \frac{364}{365}\cdot\frac{363}{365}`, R`1 - \frac{364\cdot 363}{365^2} \approx 0.0082`] } });

  lesson('Classic facts/Drawing without replacement', 'Drawing without replacement|Tirage sans remise|Extracción sin reemplazo|非復元抽出|不放回抽取',
    { s: R`Draw $n$ items at once from $N$, of which $K$ are special. Count the favourable hands: choose $k$ of the special ones and $n - k$ of the others, then divide by all possible hands $\binom Nn$ (the hypergeometric law).|On tire $n$ objets d’un coup parmi $N$, dont $K$ sont spéciaux. On compte les tirages favorables : $k$ parmi les spéciaux et $n - k$ parmi les autres, puis on divise par tous les tirages possibles $\binom Nn$ (loi hypergéométrique).|Se sacan $n$ objetos a la vez de $N$, de los que $K$ son especiales. Cuenta las manos favorables: elige $k$ de los especiales y $n - k$ de los demás, y divide entre todas las manos posibles $\binom Nn$ (ley hipergeométrica).|$N$ 個（うち特別なもの $K$ 個）から $n$ 個を同時に取る。有利な取り方：特別なものから $k$ 個、他から $n - k$ 個。全体 $\binom Nn$ で割る（超幾何分布）。|从 $N$ 个（其中 $K$ 个特殊）中一次取 $n$ 个。有利取法：从特殊中取 $k$ 个、从其他中取 $n - k$ 个，再除以全部取法 $\binom Nn$（超几何分布）。`,
      a: [Y(R`P = \frac{\binom Kk\binom{N - K}{n - k}}{\binom Nn}`)] },
    { s: R`5 cards, exactly 2 aces: $\tfrac{\binom42\binom{48}{3}}{\binom{52}{5}} = \tfrac{6\cdot 17296}{2598960} \approx 0.040$.|5 cartes, exactement 2 as : $\tfrac{\binom42\binom{48}{3}}{\binom{52}{5}} \approx 0{,}040$.|5 cartas, exactamente 2 ases: $\tfrac{\binom42\binom{48}{3}}{\binom{52}{5}} \approx 0{,}040$.|5 枚中エースちょうど 2 枚：$\approx 0.040$。|5 张牌恰 2 张 A：$\approx 0.040$。`,
      a: [F(R`\frac{\binom42\binom{48}{3}}{\binom{52}{5}} = \frac{6\cdot 17296}{2598960}`), Y(R`\approx 0.040`)] },
    { a: [F(R`6\ \text{red},\ 4\ \text{blue},\ \text{draw } 3`)],
      ex: { k: 'val', v: '0.5', q: R`An urn has 6 red and 4 blue balls. Three are drawn at once. Find the probability of exactly 2 red.|Une urne contient 6 boules rouges et 4 bleues. On en tire trois à la fois. Calculez la probabilité d’exactement 2 rouges.|Una urna tiene 6 bolas rojas y 4 azules. Se sacan tres a la vez. Halla la probabilidad de exactamente 2 rojas.|赤 6・青 4 の袋から同時に 3 個取る。ちょうど 2 個が赤の確率を求めよ。|袋中 6 红 4 蓝，同时取 3 个，求恰有 2 个红球的概率。`,
        sol: [R`\frac{\binom62\binom41}{\binom{10}{3}} = \frac{15\cdot 4}{120}`, R`= 0.5`] } });

  Cheats.tutor('probability', L);
})();
